    { r = {"HELENA"}, t = "If I have thanks, it is a dear expense." },
    { r = {"HELENA"}, t = "But herein mean I to enrich my pain," },
    { r = {"HELENA"}, t = "To have his sight thither and back again." },
    { d = "Exit Helena" },
    { d = "Act 1, Scene 2. The Same. A Room in a Cottage", h = true },
    { d = "Enter Quince, Snug, Bottom, Flute, Snout  and Starveling" },
    { r = {"QUINCE"}, t = "Is all our company here?" },
    { r = {"BOTTOM"}, t = "You were best to call them generally, man by man, according to the scrip." },
    { r = {"QUINCE"}, t = "Here is the scroll of every man’s name, which is thought fit through all Athens, to play in our interlude before the Duke and Duchess, on his wedding-day at night." },
    { r = {"BOTTOM"}, t = "First, good Peter Quince, say what the play treats on; then read the names of the actors; and so grow to a point." },
    { r = {"QUINCE"}, t = "Marry, our play is The most lamentable comedy and most cruel death of Pyramus and Thisbe." },
    { r = {"BOTTOM"}, t = "A very good piece of work, I assure you, and a merry." },
    { r = {"BOTTOM"}, t = "Now, good Peter Quince, call forth your actors by the scroll." },
    { r = {"BOTTOM"}, t = "Masters, spread yourselves." },
    { r = {"QUINCE"}, t = "Answer, as I call you. Nick Bottom, the weaver." },
    { r = {"BOTTOM"}, t = "Ready. Name what part I am for, and proceed." },
    { r = {"QUINCE"}, t = "You, Nick Bottom, are set down for Pyramus." },
    { r = {"BOTTOM"}, t = "What is Pyramus—a lover, or a tyrant?" },
    { r = {"QUINCE"}, t = "A lover, that kills himself most gallantly for love." },
    { r = {"BOTTOM"}, t = "That will ask some tears in the true performing of it." },
    { r = {"BOTTOM"}, t = "If I do it, let the audience look to their eyes." },
    { r = {"BOTTOM"}, t = "I will move storms; I will condole in some measure." },
    { r = {"BOTTOM"}, t = "To the rest—yet my chief humour is for a tyrant." },
    { r = {"BOTTOM"}, t = "I could play Ercles rarely, or a part to tear a cat in, to make all split." },
    { r = {"BOTTOM"}, t = "The raging rocks" },
    { r = {"BOTTOM"}, t = "And shivering shocks" },
    { r = {"BOTTOM"}, t = "Shall break the locks" },
    { r = {"BOTTOM"}, t = "Of prison gates," },
    { r = {"BOTTOM"}, t = "And Phibbus’ car" },
    { r = {"BOTTOM"}, t = "Shall shine from far," },
    { r = {"BOTTOM"}, t = "And make and mar" },
    { r = {"BOTTOM"}, t = "The foolish Fates." },
    { r = {"BOTTOM"}, t = "This was lofty." },
    { r = {"BOTTOM"}, t = "Now name the rest of the players." },
    { r = {"BOTTOM"}, t = "This is Ercles’ vein, a tyrant’s vein; a lover is more condoling." },
    { r = {"QUINCE"}, t = "Francis Flute, the bellows-mender." },
    { r = {"FLUTE"}, t = "Here, Peter Quince." },
    { r = {"QUINCE"}, t = "Flute, you must take Thisbe on you." },
    { r = {"FLUTE"}, t = "What is Thisbe? A wandering knight?" },
    { r = {"QUINCE"}, t = "It is the lady that Pyramus must love." },
    { r = {"FLUTE"}, t = "Nay, faith, let not me play a woman. I have a beard coming." },
    { r = {"QUINCE"}, t = "That’s all one." },
    { r = {"QUINCE"}, t = "You shall play it in a mask, and you may speak as small as you will." },
    { r = {"BOTTOM"}, t = "And I may hide my face, let me play Thisbe too." },
    { r = {"BOTTOM"}, t = "I’ll speak in a monstrous little voice; ‘Thisne, Thisne!’—‘Ah, Pyramus, my lover dear! thy Thisbe dear! and lady dear!’" },
    { r = {"QUINCE"}, t = "No, no, you must play Pyramus; and, Flute, you Thisbe." },
    { r = {"BOTTOM"}, t = "Well, proceed." },
    { r = {"QUINCE"}, t = "Robin Starveling, the tailor." },
    { r = {"STARVELING"}, t = "Here, Peter Quince." },
    { r = {"QUINCE"}, t = "Robin Starveling, you must play Thisbe’s mother." },
    { r = {"QUINCE"}, t = "Tom Snout, the tinker." },
    { r = {"QUINCE"}, t = "SNOUT" },
    { r = {"QUINCE"}, t = "Here, Peter Quince." },
    { r = {"QUINCE"}, t = "You, Pyramus’ father; myself, Thisbe’s father;" },
    { r = {"QUINCE"}, t = "Snug, the joiner, you, the lion’s part." },
    { r = {"QUINCE"}, t = "And, I hope here is a play fitted." },
    { r = {"QUINCE"}, t = "SNUG" },
    { r = {"QUINCE"}, t = "Have you the lion’s part written?" },
    { r = {"QUINCE"}, t = "Pray you, if it be, give it me, for I am slow of study." },
    { r = {"QUINCE"}, t = "You may do it extempore, for it is nothing but roaring." },
    { r = {"BOTTOM"}, t = "Let me play the lion too." },
    { r = {"BOTTOM"}, t = "I will roar that I will do any man’s heart good to hear me." },
    { r = {"BOTTOM"}, t = "I will roar that I will make the Duke say ‘Let him roar again, let him roar again.’" },
    { r = {"QUINCE"}, t = "If you should do it too terribly, you would fright the Duchess and the ladies, that they would shriek; and that were enough to hang us all." },
    { r = {"QUINCE"}, t = "ALL" },
    { r = {"QUINCE"}, t = "That would hang us every mother’s son." },
    { r = {"BOTTOM"}, t = "I grant you, friends, if you should fright the ladies out of their wits, they would have no more discretion but to hang us." },
    { r = {"BOTTOM"}, t = "But I will aggravate my voice so, that I will roar you as gently as any sucking dove; I will roar you an ’twere any nightingale." },
    { r = {"QUINCE"}, t = "You can play no part but Pyramus, for Pyramus is a sweet-faced man; a proper man as one shall see in a summer’s day; a most lovely gentleman-like man." },
    { r = {"QUINCE"}, t = "Therefore you must needs play Pyramus." },
    { r = {"BOTTOM"}, t = "Well, I will undertake it. What beard were I best to play it in?" },
    { r = {"QUINCE"}, t = "Why, what you will." },
    { r = {"BOTTOM"}, t = "I will discharge it in either your straw-colour beard, your orange-tawny beard, your purple-in-grain beard, or your" },
    { r = {"BOTTOM"}, t = "French-crown-colour beard, your perfect yellow." },
    { r = {"QUINCE"}, t = "Some of your French crowns have no hair at all, and then you will play bare-faced." },
    { r = {"QUINCE"}, t = "But, masters, here are your parts, and I am to entreat you, request you, and desire you, to con them by tomorrow night; and meet me in the palace wood, a mile without the town, by moonlight;" },
    { r = {"QUINCE"}, t = "there will we rehearse, for if we meet in the city, we shall be dogg’d with company, and our devices known." },
    { r = {"QUINCE"}, t = "In the meantime I will draw a bill of properties, such as our play wants." },
    { r = {"QUINCE"}, t = "I pray you fail me not." },
    { r = {"BOTTOM"}, t = "We will meet, and there we may rehearse most obscenely and courageously." },
    { r = {"BOTTOM"}, t = "Take pains, be perfect; adieu." },
    { r = {"QUINCE"}, t = "At the Duke’s oak we meet." },
    { r = {"BOTTOM"}, t = "Enough. Hold, or cut bow-strings." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 1. A wood near Athens", h = true },
    { d = "Enter a Fairy at one door, and Puck at another" },
    { r = {"PUCK"}, t = "How now, spirit! Whither wander you?" },
    { r = {"PUCK"}, t = "FAIRY" },
    { r = {"PUCK"}, t = "Over hill, over dale," },
    { r = {"PUCK"}, t = "Thorough bush, thorough brier," },
    { r = {"PUCK"}, t = "Over park, over pale," },
    { r = {"PUCK"}, t = "Thorough flood, thorough fire," },
    { r = {"PUCK"}, t = "I do wander everywhere," },
    { r = {"PUCK"}, t = "Swifter than the moon’s sphere;" },
    { r = {"PUCK"}, t = "And I serve the Fairy Queen," },
    { r = {"PUCK"}, t = "To dew her orbs upon the green." },
    { r = {"PUCK"}, t = "The cowslips tall her pensioners be," },
    { r = {"PUCK"}, t = "In their gold coats spots you see;" },
    { r = {"PUCK"}, t = "Those be rubies, fairy favours," },
    { r = {"PUCK"}, t = "In those freckles live their savours." },
    { r = {"PUCK"}, t = "I must go seek some dew-drops here," },
    { r = {"PUCK"}, t = "And hang a pearl in every cowslip’s ear." },
    { r = {"PUCK"}, t = "Farewell, thou lob of spirits; I’ll be gone." },
    { r = {"PUCK"}, t = "Our Queen and all her elves come here anon." },
    { r = {"PUCK"}, t = "The King doth keep his revels here tonight;" },
    { r = {"PUCK"}, t = "Take heed the Queen come not within his sight," },
    { r = {"PUCK"}, t = "For Oberon is passing fell and wrath," },
    { r = {"PUCK"}, t = "Because that she, as her attendant, hath" },
    { r = {"PUCK"}, t = "A lovely boy, stol’n from an Indian king;" },
    { r = {"PUCK"}, t = "She never had so sweet a changeling." },
    { r = {"PUCK"}, t = "And jealous Oberon would have the child" },
    { r = {"PUCK"}, t = "Knight of his train, to trace the forests wild:" },
    { r = {"PUCK"}, t = "But she perforce withholds the lovèd boy," },
    { r = {"PUCK"}, t = "Crowns him with flowers, and makes him all her joy." },
    { r = {"PUCK"}, t = "And now they never meet in grove or green," },
    { r = {"PUCK"}, t = "By fountain clear, or spangled starlight sheen," },
    { r = {"PUCK"}, t = "But they do square; that all their elves for fear" },
    { r = {"PUCK"}, t = "Creep into acorn cups, and hide them there." },
    { r = {"PUCK"}, t = "FAIRY" },
    { r = {"PUCK"}, t = "Either I mistake your shape and making quite," },
    { r = {"PUCK"}, t = "Or else you are that shrewd and knavish sprite" },
    { r = {"PUCK"}, t = "Call’d Robin Goodfellow. Are not you he" },
    { r = {"PUCK"}, t = "That frights the maidens of the villagery," },
    { r = {"PUCK"}, t = "Skim milk, and sometimes labour in the quern," },
    { r = {"PUCK"}, t = "And bootless make the breathless housewife churn," },
    { r = {"PUCK"}, t = "And sometime make the drink to bear no barm," },
    { r = {"PUCK"}, t = "Mislead night-wanderers, laughing at their harm?" },
    { r = {"PUCK"}, t = "Those that Hobgoblin call you, and sweet Puck," },
    { r = {"PUCK"}, t = "You do their work, and they shall have good luck." },
    { r = {"PUCK"}, t = "Are not you he?" },
    { r = {"PUCK"}, t = "Thou speak’st aright;" },
    { r = {"PUCK"}, t = "I am that merry wanderer of the night." },
    { r = {"PUCK"}, t = "I jest to Oberon, and make him smile," },
    { r = {"PUCK"}, t = "When I a fat and bean-fed horse beguile," },
    { r = {"PUCK"}, t = "Neighing in likeness of a filly foal;" },
    { r = {"PUCK"}, t = "And sometime lurk I in a gossip’s bowl" },
    { r = {"PUCK"}, t = "In very likeness of a roasted crab," },
    { r = {"PUCK"}, t = "And, when she drinks, against her lips I bob," },
    { r = {"PUCK"}, t = "And on her withered dewlap pour the ale." },
    { r = {"PUCK"}, t = "The wisest aunt, telling the saddest tale," },
    { r = {"PUCK"}, t = "Sometime for three-foot stool mistaketh me;" },
    { r = {"PUCK"}, t = "Then slip I from her bum, down topples she," },
    { r = {"PUCK"}, t = "And ‘tailor’ cries, and falls into a cough;" },
    { r = {"PUCK"}, t = "And then the whole quire hold their hips and loffe" },
    { r = {"PUCK"}, t = "And waxen in their mirth, and neeze, and swear" },
    { r = {"PUCK"}, t = "A merrier hour was never wasted there." },
    { r = {"PUCK"}, t = "But room, fairy. Here comes Oberon." },
    { r = {"PUCK"}, t = "FAIRY" },
    { r = {"PUCK"}, t = "And here my mistress. Would that he were gone!" },
    { d = "Enter Oberon at one door, with his Train, and Titania at another, with hers" },
    { r = {"OBERON"}, t = "Ill met by moonlight, proud Titania." },
    { r = {"TITANIA"}, t = "What, jealous Oberon! Fairies, skip hence;" },
    { r = {"TITANIA"}, t = "I have forsworn his bed and company." },
    { r = {"OBERON"}, t = "Tarry, rash wanton; am not I thy lord?" },
    { r = {"TITANIA"}, t = "Then I must be thy lady; but I know" },
    { r = {"TITANIA"}, t = "When thou hast stol’n away from fairyland," },
    { r = {"TITANIA"}, t = "And in the shape of Corin sat all day" },
    { r = {"TITANIA"}, t = "Playing on pipes of corn, and versing love" },
    { r = {"TITANIA"}, t = "To amorous Phillida. Why art thou here," },
    { r = {"TITANIA"}, t = "Come from the farthest steep of India," },
    { r = {"TITANIA"}, t = "But that, forsooth, the bouncing Amazon," },
    { r = {"TITANIA"}, t = "Your buskin’d mistress and your warrior love," },
    { r = {"TITANIA"}, t = "To Theseus must be wedded; and you come" },
    { r = {"TITANIA"}, t = "To give their bed joy and prosperity?" },
    { r = {"OBERON"}, t = "How canst thou thus, for shame, Titania," },
    { r = {"OBERON"}, t = "Glance at my credit with Hippolyta," },
    { r = {"OBERON"}, t = "Knowing I know thy love to Theseus?" },
    { r = {"OBERON"}, t = "Didst not thou lead him through the glimmering night" },
    { r = {"OBERON"}, t = "From Perigenia, whom he ravished?" },
    { r = {"OBERON"}, t = "And make him with fair Aegles break his faith," },
    { r = {"OBERON"}, t = "With Ariadne and Antiopa?" },
    { r = {"TITANIA"}, t = "These are the forgeries of jealousy:" },
    { r = {"TITANIA"}, t = "And never, since the middle summer’s spring," },
    { r = {"TITANIA"}, t = "Met we on hill, in dale, forest, or mead," },
    { r = {"TITANIA"}, t = "By pavèd fountain, or by rushy brook," },
    { r = {"TITANIA"}, t = "Or on the beachèd margent of the sea," },
    { r = {"TITANIA"}, t = "To dance our ringlets to the whistling wind," },
    { r = {"TITANIA"}, t = "But with thy brawls thou hast disturb’d our sport." },
    { r = {"TITANIA"}, t = "Therefore the winds, piping to us in vain," },
    { r = {"TITANIA"}, t = "As in revenge, have suck’d up from the sea" },
    { r = {"TITANIA"}, t = "Contagious fogs; which, falling in the land," },
    { r = {"TITANIA"}, t = "Hath every pelting river made so proud" },
    { r = {"TITANIA"}, t = "That they have overborne their continents." },
    { r = {"TITANIA"}, t = "The ox hath therefore stretch’d his yoke in vain," },
    { r = {"TITANIA"}, t = "The ploughman lost his sweat, and the green corn" },
    { r = {"TITANIA"}, t = "Hath rotted ere his youth attain’d a beard." },
    { r = {"TITANIA"}, t = "The fold stands empty in the drownèd field," },
    { r = {"TITANIA"}, t = "And crows are fatted with the murrion flock;" },
    { r = {"TITANIA"}, t = "The nine-men’s-morris is fill’d up with mud," },
    { r = {"TITANIA"}, t = "And the quaint mazes in the wanton green," },
    { r = {"TITANIA"}, t = "For lack of tread, are undistinguishable." },
    { r = {"TITANIA"}, t = "The human mortals want their winter here." },
    { r = {"TITANIA"}, t = "No night is now with hymn or carol blest." },
    { r = {"TITANIA"}, t = "Therefore the moon, the governess of floods," },
    { r = {"TITANIA"}, t = "Pale in her anger, washes all the air," },
    { r = {"TITANIA"}, t = "That rheumatic diseases do abound." },
    { r = {"TITANIA"}, t = "And thorough this distemperature we see" },
    { r = {"TITANIA"}, t = "The seasons alter: hoary-headed frosts" },
    { r = {"TITANIA"}, t = "Fall in the fresh lap of the crimson rose;" },
    { r = {"TITANIA"}, t = "And on old Hiems’ thin and icy crown" },
    { r = {"TITANIA"}, t = "An odorous chaplet of sweet summer buds" },
    { r = {"TITANIA"}, t = "Is, as in mockery, set. The spring, the summer," },
    { r = {"TITANIA"}, t = "The childing autumn, angry winter, change" },
    { r = {"TITANIA"}, t = "Their wonted liveries; and the mazed world," },
    { r = {"TITANIA"}, t = "By their increase, now knows not which is which." },
    { r = {"TITANIA"}, t = "And this same progeny of evils comes" },
    { r = {"TITANIA"}, t = "From our debate, from our dissension;" },
    { r = {"TITANIA"}, t = "We are their parents and original." },
    { r = {"OBERON"}, t = "Do you amend it, then. It lies in you." },
    { r = {"OBERON"}, t = "Why should Titania cross her Oberon?" },
    { r = {"OBERON"}, t = "I do but beg a little changeling boy" },
    { r = {"OBERON"}, t = "To be my henchman." },
    { r = {"TITANIA"}, t = "Set your heart at rest;" },
    { r = {"TITANIA"}, t = "The fairyland buys not the child of me." },
    { r = {"TITANIA"}, t = "His mother was a vot’ress of my order," },
    { r = {"TITANIA"}, t = "And in the spicèd Indian air, by night," },
    { r = {"TITANIA"}, t = "Full often hath she gossip’d by my side;" },
    { r = {"TITANIA"}, t = "And sat with me on Neptune’s yellow sands," },
    { r = {"TITANIA"}, t = "Marking th’ embarkèd traders on the flood," },
    { r = {"TITANIA"}, t = "When we have laugh’d to see the sails conceive," },
    { r = {"TITANIA"}, t = "And grow big-bellied with the wanton wind;" },
    { r = {"TITANIA"}, t = "Which she, with pretty and with swimming gait" },
    { r = {"TITANIA"}, t = "Following (her womb then rich with my young squire)," },
    { r = {"TITANIA"}, t = "Would imitate, and sail upon the land," },
    { r = {"TITANIA"}, t = "To fetch me trifles, and return again," },
    { r = {"TITANIA"}, t = "As from a voyage, rich with merchandise." },
    { r = {"TITANIA"}, t = "But she, being mortal, of that boy did die;" },
    { r = {"TITANIA"}, t = "And for her sake do I rear up her boy," },
    { r = {"TITANIA"}, t = "And for her sake I will not part with him." },
    { r = {"OBERON"}, t = "How long within this wood intend you stay?" },
    { r = {"TITANIA"}, t = "Perchance till after Theseus’ wedding-day." },
    { r = {"TITANIA"}, t = "If you will patiently dance in our round," },
    { r = {"TITANIA"}, t = "And see our moonlight revels, go with us;" },
    { r = {"TITANIA"}, t = "If not, shun me, and I will spare your haunts." },
    { r = {"OBERON"}, t = "Give me that boy and I will go with thee." },
    { r = {"TITANIA"}, t = "Not for thy fairy kingdom. Fairies, away." },
    { r = {"TITANIA"}, t = "We shall chide downright if I longer stay." },
    { d = "Exit Titania with her Train" },
    { r = {"OBERON"}, t = "Well, go thy way. Thou shalt not from this grove" },
    { r = {"OBERON"}, t = "Till I torment thee for this injury.—" },
    { r = {"OBERON"}, t = "My gentle Puck, come hither. Thou rememb’rest" },
    { r = {"OBERON"}, t = "Since once I sat upon a promontory," },
    { r = {"OBERON"}, t = "And heard a mermaid on a dolphin’s back" },
    { r = {"OBERON"}, t = "Uttering such dulcet and harmonious breath" },
    { r = {"OBERON"}, t = "That the rude sea grew civil at her song" },
    { r = {"OBERON"}, t = "And certain stars shot madly from their spheres" },
    { r = {"OBERON"}, t = "To hear the sea-maid’s music." },
    { r = {"PUCK"}, t = "I remember." },
    { r = {"OBERON"}, t = "That very time I saw, (but thou couldst not)," },
    { r = {"OBERON"}, t = "Flying between the cold moon and the earth," },
    { r = {"OBERON"}, t = "Cupid all arm’d: a certain aim he took" },
    { r = {"OBERON"}, t = "At a fair vestal, thronèd by the west," },
    { r = {"OBERON"}, t = "And loos’d his love-shaft smartly from his bow" },
    { r = {"OBERON"}, t = "As it should pierce a hundred thousand hearts." },
    { r = {"OBERON"}, t = "But I might see young Cupid’s fiery shaft" },
    { r = {"OBERON"}, t = "Quench’d in the chaste beams of the watery moon;" },
    { r = {"OBERON"}, t = "And the imperial votress passed on," },
    { r = {"OBERON"}, t = "In maiden meditation, fancy-free." },
    { r = {"OBERON"}, t = "Yet mark’d I where the bolt of Cupid fell:" },
    { r = {"OBERON"}, t = "It fell upon a little western flower," },
    { r = {"OBERON"}, t = "Before milk-white, now purple with love’s wound," },
    { r = {"OBERON"}, t = "And maidens call it love-in-idleness." },
    { r = {"OBERON"}, t = "Fetch me that flower, the herb I showed thee once:" },
    { r = {"OBERON"}, t = "The juice of it on sleeping eyelids laid" },
    { r = {"OBERON"}, t = "Will make or man or woman madly dote" },
    { r = {"OBERON"}, t = "Upon the next live creature that it sees." },
    { r = {"OBERON"}, t = "Fetch me this herb, and be thou here again" },
    { r = {"OBERON"}, t = "Ere the leviathan can swim a league." },
    { r = {"PUCK"}, t = "I’ll put a girdle round about the earth" },
    { r = {"PUCK"}, t = "In forty minutes." },
    { d = "Exit Puck" },
    { r = {"OBERON"}, t = "Having once this juice," },
    { r = {"OBERON"}, t = "I’ll watch Titania when she is asleep," },
    { r = {"OBERON"}, t = "And drop the liquor of it in her eyes:" },
    { r = {"OBERON"}, t = "The next thing then she waking looks upon" },
    { r = {"OBERON"}, t = "(Be it on lion, bear, or wolf, or bull," },
    { r = {"OBERON"}, t = "On meddling monkey, or on busy ape)" },
    { r = {"OBERON"}, t = "She shall pursue it with the soul of love." },
    { r = {"OBERON"}, t = "And ere I take this charm from off her sight" },
    { r = {"OBERON"}, t = "(As I can take it with another herb)" },
    { r = {"OBERON"}, t = "I’ll make her render up her page to me." },
    { r = {"OBERON"}, t = "But who comes here? I am invisible;" },
    { r = {"OBERON"}, t = "And I will overhear their conference." },
    { d = "Enter Demetrius, Helena following him" },
    { r = {"DEMETRIUS"}, t = "I love thee not, therefore pursue me not." },
    { r = {"DEMETRIUS"}, t = "Where is Lysander and fair Hermia?" },
    { r = {"DEMETRIUS"}, t = "The one I’ll slay, the other slayeth me." },
    { r = {"DEMETRIUS"}, t = "Thou told’st me they were stol’n into this wood," },
    { r = {"DEMETRIUS"}, t = "And here am I, and wode within this wood" },
    { r = {"DEMETRIUS"}, t = "Because I cannot meet with Hermia." },
    { r = {"DEMETRIUS"}, t = "Hence, get thee gone, and follow me no more." },
    { r = {"HELENA"}, t = "You draw me, you hard-hearted adamant," },
    { r = {"HELENA"}, t = "But yet you draw not iron, for my heart" },
    { r = {"HELENA"}, t = "Is true as steel. Leave you your power to draw," },
    { r = {"HELENA"}, t = "And I shall have no power to follow you." },
    { r = {"DEMETRIUS"}, t = "Do I entice you? Do I speak you fair?" },
    { r = {"DEMETRIUS"}, t = "Or rather do I not in plainest truth" },
    { r = {"DEMETRIUS"}, t = "Tell you I do not, nor I cannot love you?" },
    { r = {"HELENA"}, t = "And even for that do I love you the more." },
    { r = {"HELENA"}, t = "I am your spaniel; and, Demetrius," },
    { r = {"HELENA"}, t = "The more you beat me, I will fawn on you." },
    { r = {"HELENA"}, t = "Use me but as your spaniel, spurn me, strike me," },
    { r = {"HELENA"}, t = "Neglect me, lose me; only give me leave," },
    { r = {"HELENA"}, t = "Unworthy as I am, to follow you." },
    { r = {"HELENA"}, t = "What worser place can I beg in your love," },
    { r = {"HELENA"}, t = "(And yet a place of high respect with me)" },
    { r = {"HELENA"}, t = "Than to be usèd as you use your dog?" },
    { r = {"DEMETRIUS"}, t = "Tempt not too much the hatred of my spirit;" },
    { r = {"DEMETRIUS"}, t = "For I am sick when I do look on thee." },
    { r = {"HELENA"}, t = "And I am sick when I look not on you." },
    { r = {"DEMETRIUS"}, t = "You do impeach your modesty too much" },
    { r = {"DEMETRIUS"}, t = "To leave the city and commit yourself" },
    { r = {"DEMETRIUS"}, t = "Into the hands of one that loves you not," },
    { r = {"DEMETRIUS"}, t = "To trust the opportunity of night" },
    { r = {"DEMETRIUS"}, t = "And the ill counsel of a desert place," },
    { r = {"DEMETRIUS"}, t = "With the rich worth of your virginity." },
    { r = {"HELENA"}, t = "Your virtue is my privilege: for that" },
    { r = {"HELENA"}, t = "It is not night when I do see your face," },
    { r = {"HELENA"}, t = "Therefore I think I am not in the night;" },
    { r = {"HELENA"}, t = "Nor doth this wood lack worlds of company," },
    { r = {"HELENA"}, t = "For you, in my respect, are all the world." },
    { r = {"HELENA"}, t = "Then how can it be said I am alone" },
    { r = {"HELENA"}, t = "When all the world is here to look on me?" },
    { r = {"DEMETRIUS"}, t = "I’ll run from thee and hide me in the brakes," },
    { r = {"DEMETRIUS"}, t = "And leave thee to the mercy of wild beasts." },
    { r = {"HELENA"}, t = "The wildest hath not such a heart as you." },
    { r = {"HELENA"}, t = "Run when you will, the story shall be chang’d;" },
    { r = {"HELENA"}, t = "Apollo flies, and Daphne holds the chase;" },
    { r = {"HELENA"}, t = "The dove pursues the griffin, the mild hind" },
    { r = {"HELENA"}, t = "Makes speed to catch the tiger. Bootless speed," },
    { r = {"HELENA"}, t = "When cowardice pursues and valour flies!" },
    { r = {"DEMETRIUS"}, t = "I will not stay thy questions. Let me go," },
    { r = {"DEMETRIUS"}, t = "Or if thou follow me, do not believe" },
    { r = {"DEMETRIUS"}, t = "But I shall do thee mischief in the wood." },
    { r = {"HELENA"}, t = "Ay, in the temple, in the town, the field," },
    { r = {"HELENA"}, t = "You do me mischief. Fie, Demetrius!" },
    { r = {"HELENA"}, t = "Your wrongs do set a scandal on my sex." },
    { r = {"HELENA"}, t = "We cannot fight for love as men may do." },
    { r = {"HELENA"}, t = "We should be woo’d, and were not made to woo." },
    { d = "Exit Demetrius" },
    { r = {"HELENA"}, t = "I’ll follow thee, and make a heaven of hell," },
    { r = {"HELENA"}, t = "To die upon the hand I love so well." },
    { d = "Exit Helena" },
    { r = {"OBERON"}, t = "Fare thee well, nymph. Ere he do leave this grove," },
    { r = {"OBERON"}, t = "Thou shalt fly him, and he shall seek thy love." },
    { d = "Enter Puck" },
    { r = {"OBERON"}, t = "Hast thou the flower there? Welcome, wanderer." },
    { r = {"PUCK"}, t = "Ay, there it is." },
    { r = {"OBERON"}, t = "I pray thee give it me." },
    { r = {"OBERON"}, t = "I know a bank where the wild thyme blows," },
    { r = {"OBERON"}, t = "Where oxlips and the nodding violet grows," },
    { r = {"OBERON"}, t = "Quite over-canopied with luscious woodbine," },
    { r = {"OBERON"}, t = "With sweet musk-roses, and with eglantine." },
    { r = {"OBERON"}, t = "There sleeps Titania sometime of the night," },
    { r = {"OBERON"}, t = "Lull’d in these flowers with dances and delight;" },
    { r = {"OBERON"}, t = "And there the snake throws her enamell’d skin," },
    { r = {"OBERON"}, t = "Weed wide enough to wrap a fairy in." },
    { r = {"OBERON"}, t = "And with the juice of this I’ll streak her eyes," },
    { r = {"OBERON"}, t = "And make her full of hateful fantasies." },
    { r = {"OBERON"}, t = "Take thou some of it, and seek through this grove:" },
    { r = {"OBERON"}, t = "A sweet Athenian lady is in love" },
    { r = {"OBERON"}, t = "With a disdainful youth. Anoint his eyes;" },
    { r = {"OBERON"}, t = "But do it when the next thing he espies" },
    { r = {"OBERON"}, t = "May be the lady. Thou shalt know the man" },
    { r = {"OBERON"}, t = "By the Athenian garments he hath on." },
    { r = {"OBERON"}, t = "Effect it with some care, that he may prove" },
    { r = {"OBERON"}, t = "More fond on her than she upon her love:" },
    { r = {"OBERON"}, t = "And look thou meet me ere the first cock crow." },
    { r = {"PUCK"}, t = "Fear not, my lord, your servant shall do so." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 2. Another part of the wood", h = true },
    { d = "Enter Titania with her Train" },
    { r = {"TITANIA"}, t = "Come, now a roundel and a fairy song;" },
    { r = {"TITANIA"}, t = "Then for the third part of a minute, hence;" },
    { r = {"TITANIA"}, t = "Some to kill cankers in the musk-rose buds;" },
    { r = {"TITANIA"}, t = "Some war with reremice for their leathern wings," },
    { r = {"TITANIA"}, t = "To make my small elves coats; and some keep back" },
    { r = {"TITANIA"}, t = "The clamorous owl, that nightly hoots and wonders" },
    { r = {"TITANIA"}, t = "At our quaint spirits. Sing me now asleep;" },
    { r = {"TITANIA"}, t = "Then to your offices, and let me rest." },
    { r = {"TITANIA"}, t = "Fairies sing." },
    { r = {"FIRST FAIRY"}, t = "You spotted snakes with double tongue," },
    { r = {"FIRST FAIRY"}, t = "Thorny hedgehogs, be not seen;" },
    { r = {"FIRST FAIRY"}, t = "Newts and blind-worms do no wrong," },
    { r = {"FIRST FAIRY"}, t = "Come not near our Fairy Queen:" },
    { r = {"CHORUS"}, t = "Philomel, with melody," },
    { r = {"CHORUS"}, t = "Sing in our sweet lullaby:" },
    { r = {"CHORUS"}, t = "Lulla, lulla, lullaby; lulla, lulla, lullaby." },
    { r = {"CHORUS"}, t = "Never harm, nor spell, nor charm," },
    { r = {"CHORUS"}, t = "Come our lovely lady nigh;" },
    { r = {"CHORUS"}, t = "So good night, with lullaby." },
    { r = {"FIRST FAIRY"}, t = "Weaving spiders, come not here;" },
    { r = {"FIRST FAIRY"}, t = "Hence, you long-legg’d spinners, hence." },
    { r = {"FIRST FAIRY"}, t = "Beetles black, approach not near;" },
    { r = {"FIRST FAIRY"}, t = "Worm nor snail do no offence." },
    { r = {"CHORUS"}, t = "Philomel with melody, &c." },
    { r = {"SECOND FAIRY"}, t = "Hence away! Now all is well." },
    { r = {"SECOND FAIRY"}, t = "One aloof stand sentinel." },
    { r = {"TITANIA"}, d = "Exeunt Fairies. Titania sleeps", e = "/sleep" },
    { d = "Enter Oberon" },
    { r = {"OBERON"}, t = "What thou seest when thou dost wake," },
    { d = "Squeezes the flower on  Titania’s eyelids" },
    { r = {"OBERON"}, t = "Do it for thy true love take;" },
    { r = {"OBERON"}, t = "Love and languish for his sake." },
    { r = {"OBERON"}, t = "Be it ounce, or cat, or bear," },
    { r = {"OBERON"}, t = "Pard, or boar with bristled hair," },
    { r = {"OBERON"}, t = "In thy eye that shall appear" },
    { r = {"OBERON"}, t = "When thou wak’st, it is thy dear." },
    { r = {"OBERON"}, t = "Wake when some vile thing is near." },
    { d = "Exit" },
    { d = "Enter Lysander and Hermia" },
    { r = {"LYSANDER"}, t = "Fair love, you faint with wand’ring in the wood." },
    { r = {"LYSANDER"}, t = "And, to speak troth, I have forgot our way." },
    { r = {"LYSANDER"}, t = "We’ll rest us, Hermia, if you think it good," },
    { r = {"LYSANDER"}, t = "And tarry for the comfort of the day." },
    { r = {"HERMIA"}, t = "Be it so, Lysander: find you out a bed," },
    { r = {"HERMIA"}, t = "For I upon this bank will rest my head." },
    { r = {"LYSANDER"}, t = "One turf shall serve as pillow for us both;" },
    { r = {"LYSANDER"}, t = "One heart, one bed, two bosoms, and one troth." },
    { r = {"HERMIA"}, t = "Nay, good Lysander; for my sake, my dear," },
    { r = {"HERMIA"}, t = "Lie further off yet, do not lie so near." },
    { r = {"LYSANDER"}, t = "O take the sense, sweet, of my innocence!" },
    { r = {"LYSANDER"}, t = "Love takes the meaning in love’s conference." },
    { r = {"LYSANDER"}, t = "I mean that my heart unto yours is knit," },
    { r = {"LYSANDER"}, t = "So that but one heart we can make of it:" },
    { r = {"LYSANDER"}, t = "Two bosoms interchainèd with an oath," },
    { r = {"LYSANDER"}, t = "So then two bosoms and a single troth." },
    { r = {"LYSANDER"}, t = "Then by your side no bed-room me deny;" },
    { r = {"LYSANDER"}, t = "For lying so, Hermia, I do not lie." },
    { r = {"HERMIA"}, t = "Lysander riddles very prettily." },
    { r = {"HERMIA"}, t = "Now much beshrew my manners and my pride," },
    { r = {"HERMIA"}, t = "If Hermia meant to say Lysander lied!" },
    { r = {"HERMIA"}, t = "But, gentle friend, for love and courtesy" },
    { r = {"HERMIA"}, t = "Lie further off, in human modesty," },
    { r = {"HERMIA"}, t = "Such separation as may well be said" },
    { r = {"HERMIA"}, t = "Becomes a virtuous bachelor and a maid," },
    { r = {"HERMIA"}, t = "So far be distant; and good night, sweet friend:" },
    { r = {"HERMIA"}, t = "Thy love ne’er alter till thy sweet life end!" },
    { r = {"LYSANDER"}, t = "Amen, amen, to that fair prayer say I;" },
    { r = {"LYSANDER"}, t = "And then end life when I end loyalty!" },
    { r = {"LYSANDER"}, t = "Here is my bed. Sleep give thee all his rest!" },
    { r = {"HERMIA"}, t = "With half that wish the wisher’s eyes be pressed!" },
    { d = "They sleep" },
    { d = "Enter Puck" },
    { r = {"PUCK"}, t = "Through the forest have I gone," },
    { r = {"PUCK"}, t = "But Athenian found I none," },
    { r = {"PUCK"}, t = "On whose eyes I might approve" },
    { r = {"PUCK"}, t = "This flower’s force in stirring love." },
    { r = {"PUCK"}, t = "Night and silence! Who is here?" },
    { r = {"PUCK"}, t = "Weeds of Athens he doth wear:" },
    { r = {"PUCK"}, t = "This is he, my master said," },
    { r = {"PUCK"}, t = "Despisèd the Athenian maid;" },
    { r = {"PUCK"}, t = "And here the maiden, sleeping sound," },
    { r = {"PUCK"}, t = "On the dank and dirty ground." },
    { r = {"PUCK"}, t = "Pretty soul, she durst not lie" },
    { r = {"PUCK"}, t = "Near this lack-love, this kill-courtesy." },
    { r = {"PUCK"}, t = "Churl, upon thy eyes I throw" },
    { r = {"PUCK"}, t = "All the power this charm doth owe;" },
    { r = {"PUCK"}, t = "When thou wak’st let love forbid" },
    { r = {"PUCK"}, t = "Sleep his seat on thy eyelid." },
    { r = {"PUCK"}, t = "So awake when I am gone;" },
    { r = {"PUCK"}, t = "For I must now to Oberon." },
    { d = "Exit" },
    { d = "Enter Demetrius and Helena, running" },
    { r = {"HELENA"}, t = "Stay, though thou kill me, sweet Demetrius." },
    { r = {"DEMETRIUS"}, t = "I charge thee, hence, and do not haunt me thus." },
    { r = {"HELENA"}, t = "O, wilt thou darkling leave me? Do not so." },
    { r = {"DEMETRIUS"}, t = "Stay, on thy peril; I alone will go." },
    { d = "Exit Demetrius" },
    { r = {"HELENA"}, t = "O, I am out of breath in this fond chase!" },
    { r = {"HELENA"}, t = "The more my prayer, the lesser is my grace." },
    { r = {"HELENA"}, t = "Happy is Hermia, wheresoe’er she lies," },
    { r = {"HELENA"}, t = "For she hath blessèd and attractive eyes." },
    { r = {"HELENA"}, t = "How came her eyes so bright? Not with salt tears." },
    { r = {"HELENA"}, t = "If so, my eyes are oftener wash’d than hers." },
    { r = {"HELENA"}, t = "No, no, I am as ugly as a bear," },
    { r = {"HELENA"}, t = "For beasts that meet me run away for fear:" },
    { r = {"HELENA"}, t = "Therefore no marvel though Demetrius" },
    { r = {"HELENA"}, t = "Do, as a monster, fly my presence thus." },
    { r = {"HELENA"}, t = "What wicked and dissembling glass of mine" },
    { r = {"HELENA"}, t = "Made me compare with Hermia’s sphery eyne?" },
    { r = {"HELENA"}, t = "But who is here? Lysander, on the ground!" },
    { r = {"HELENA"}, t = "Dead or asleep? I see no blood, no wound." },
    { r = {"HELENA"}, t = "Lysander, if you live, good sir, awake." },
    { r = {"LYSANDER"}, t = "And run through fire I will for thy sweet sake.", d = "Waking", e = "/stand" },
    { r = {"LYSANDER"}, t = "Transparent Helena! Nature shows art," },
    { r = {"LYSANDER"}, t = "That through thy bosom makes me see thy heart." },
    { r = {"LYSANDER"}, t = "Where is Demetrius? O, how fit a word" },
    { r = {"LYSANDER"}, t = "Is that vile name to perish on my sword!" },
    { r = {"HELENA"}, t = "Do not say so, Lysander, say not so." },
    { r = {"HELENA"}, t = "What though he love your Hermia? Lord, what though?" },
    { r = {"HELENA"}, t = "Yet Hermia still loves you. Then be content." },
    { r = {"LYSANDER"}, t = "Content with Hermia? No, I do repent" },
    { r = {"LYSANDER"}, t = "The tedious minutes I with her have spent." },
    { r = {"LYSANDER"}, t = "Not Hermia, but Helena I love." },
    { r = {"LYSANDER"}, t = "Who will not change a raven for a dove?" },
    { r = {"LYSANDER"}, t = "The will of man is by his reason sway’d," },
    { r = {"LYSANDER"}, t = "And reason says you are the worthier maid." },
    { r = {"LYSANDER"}, t = "Things growing are not ripe until their season;" },
    { r = {"LYSANDER"}, t = "So I, being young, till now ripe not to reason;" },
    { r = {"LYSANDER"}, t = "And touching now the point of human skill," },
    { r = {"LYSANDER"}, t = "Reason becomes the marshal to my will," },
    { r = {"LYSANDER"}, t = "And leads me to your eyes, where I o’erlook" },
    { r = {"LYSANDER"}, t = "Love’s stories, written in love’s richest book." },
    { r = {"HELENA"}, t = "Wherefore was I to this keen mockery born?" },
    { r = {"HELENA"}, t = "When at your hands did I deserve this scorn?" },
    { r = {"HELENA"}, t = "Is’t not enough, is’t not enough, young man," },
    { r = {"HELENA"}, t = "That I did never, no, nor never can" },
    { r = {"HELENA"}, t = "Deserve a sweet look from Demetrius’ eye," },
    { r = {"HELENA"}, t = "But you must flout my insufficiency?" },
    { r = {"HELENA"}, t = "Good troth, you do me wrong, good sooth, you do," },
    { r = {"HELENA"}, t = "In such disdainful manner me to woo." },
    { r = {"HELENA"}, t = "But fare you well; perforce I must confess," },
    { r = {"HELENA"}, t = "I thought you lord of more true gentleness." },
    { r = {"HELENA"}, t = "O, that a lady of one man refus’d," },
    { r = {"HELENA"}, t = "Should of another therefore be abus’d!" },
    { d = "Exit" },
    { r = {"LYSANDER"}, t = "She sees not Hermia. Hermia, sleep thou there," },
    { r = {"LYSANDER"}, t = "And never mayst thou come Lysander near!" },
    { r = {"LYSANDER"}, t = "For, as a surfeit of the sweetest things" },
    { r = {"LYSANDER"}, t = "The deepest loathing to the stomach brings;" },
    { r = {"LYSANDER"}, t = "Or as the heresies that men do leave" },
    { r = {"LYSANDER"}, t = "Are hated most of those they did deceive;" },
    { r = {"LYSANDER"}, t = "So thou, my surfeit and my heresy," },
    { r = {"LYSANDER"}, t = "Of all be hated, but the most of me!" },
    { r = {"LYSANDER"}, t = "And, all my powers, address your love and might" },
    { r = {"LYSANDER"}, t = "To honour Helen, and to be her knight!" },
    { d = "Exit" },
    { r = {"HERMIA"}, t = "Help me, Lysander, help me! Do thy best", d = "Starting" },
    { r = {"HERMIA"}, t = "To pluck this crawling serpent from my breast!" },
    { r = {"HERMIA"}, t = "Ay me, for pity! What a dream was here!" },
    { r = {"HERMIA"}, t = "Lysander, look how I do quake with fear." },
    { r = {"HERMIA"}, t = "Methought a serpent eat my heart away," },
    { r = {"HERMIA"}, t = "And you sat smiling at his cruel prey." },
    { r = {"HERMIA"}, t = "Lysander! What, removed? Lysander! lord!" },
    { r = {"HERMIA"}, t = "What, out of hearing? Gone? No sound, no word?" },
    { r = {"HERMIA"}, t = "Alack, where are you? Speak, and if you hear;" },
    { r = {"HERMIA"}, t = "Speak, of all loves! I swoon almost with fear." },
    { r = {"HERMIA"}, t = "No? Then I well perceive you are not nigh." },
    { r = {"HERMIA"}, t = "Either death or you I’ll find immediately." },
    { d = "Exit" },
    { d = "Act 3, Scene 1. The Wood.", h = true },
    { d = "The Queen of Fairies still lying asleep." },
    { d = "Enter Bottom, Quince, Snout, Starveling, Snug and Flute" },
    { r = {"BOTTOM"}, t = "Are we all met?" },
    { r = {"QUINCE"}, t = "Pat, pat; and here’s a marvellous convenient place for our rehearsal." },
    { r = {"QUINCE"}, t = "This green plot shall be our stage, this hawthorn brake our tiring-house; and we will do it in action, as we will do it before the Duke." },
    { r = {"BOTTOM"}, t = "Peter Quince?" },
    { r = {"QUINCE"}, t = "What sayest thou, bully Bottom?" },
    { r = {"BOTTOM"}, t = "There are things in this comedy of Pyramus and Thisbe that will never please." },
    { r = {"BOTTOM"}, t = "First, Pyramus must draw a sword to kill himself; which the ladies cannot abide." },
    { r = {"BOTTOM"}, t = "How answer you that?" },
    { r = {"BOTTOM"}, t = "SNOUT" },
    { r = {"BOTTOM"}, t = "By’r lakin, a parlous fear." },
    { r = {"STARVELING"}, t = "I believe we must leave the killing out, when all is done." },
    { r = {"BOTTOM"}, t = "Not a whit; I have a device to make all well." },
    { r = {"BOTTOM"}, t = "Write me a prologue, and let the prologue seem to say we will do no harm with our swords, and that Pyramus is not killed indeed; and for the more better assurance, tell them that I Pyramus am not Pyramus but Bottom the weaver." },
    { r = {"BOTTOM"}, t = "This will put them out of fear." },
    { r = {"QUINCE"}, t = "Well, we will have such a prologue; and it shall be written in eight and six." },
    { r = {"BOTTOM"}, t = "No, make it two more; let it be written in eight and eight." },
    { r = {"BOTTOM"}, t = "SNOUT" },
    { r = {"BOTTOM"}, t = "Will not the ladies be afeard of the lion?" },
    { r = {"STARVELING"}, t = "I fear it, I promise you." },
    { r = {"BOTTOM"}, t = "Masters, you ought to consider with yourselves, to bring in (God shield us!) a lion among ladies is a most dreadful thing." },
    { r = {"BOTTOM"}, t = "For there is not a more fearful wild-fowl than your lion living; and we ought to look to it." },
    { r = {"BOTTOM"}, t = "SNOUT" },
    { r = {"BOTTOM"}, t = "Therefore another prologue must tell he is not a lion." },
    { r = {"BOTTOM"}, t = "Nay, you must name his name, and half his face must be seen through the lion’s neck; and he himself must speak through, saying thus, or to the same defect:" },
    { r = {"BOTTOM"}, t = "‘Ladies,’ or, ‘Fair ladies, I would wish you,’ or, ‘I would request you,’ or, ’I would entreat you, not to fear, not to tremble: my life for yours." },
    { r = {"BOTTOM"}, t = "If you think I come hither as a lion, it were pity of my life." },
    { r = {"BOTTOM"}, t = "No, I am no such thing; I am a man as other men are’: and there, indeed, let him name his name, and tell them plainly he is Snug the joiner." },
    { r = {"QUINCE"}, t = "Well, it shall be so." },
    { r = {"QUINCE"}, t = "But there is two hard things: that is, to bring the moonlight into a chamber, for you know, Pyramus and Thisbe meet by moonlight." },
    { r = {"QUINCE"}, t = "SNOUT" },
    { r = {"QUINCE"}, t = "Doth the moon shine that night we play our play?" },
    { r = {"BOTTOM"}, t = "A calendar, a calendar!" },
    { r = {"BOTTOM"}, t = "Look in the almanack; find out moonshine, find out moonshine." },
    { r = {"QUINCE"}, t = "Yes, it doth shine that night." },
    { r = {"BOTTOM"}, t = "Why, then may you leave a casement of the great chamber window, where we play, open; and the moon may shine in at the casement." },
    { r = {"QUINCE"}, t = "Ay; or else one must come in with a bush of thorns and a lantern, and say he comes to disfigure or to present the person of Moonshine." },
    { r = {"QUINCE"}, t = "Then there is another thing: we must have a wall in the great chamber; for Pyramus and Thisbe, says the story, did talk through the chink of a wall." },
    { r = {"QUINCE"}, t = "SNOUT" },
    { r = {"QUINCE"}, t = "You can never bring in a wall. What say you, Bottom?" },
    { r = {"BOTTOM"}, t = "Some man or other must present Wall." },
    { r = {"BOTTOM"}, t = "And let him have some plaster, or some loam, or some rough-cast about him, to signify wall; and let him hold his fingers thus, and through that cranny shall Pyramus and Thisbe whisper." },
    { r = {"QUINCE"}, t = "If that may be, then all is well." },
    { r = {"QUINCE"}, t = "Come, sit down, every mother’s son, and rehearse your parts." },
    { r = {"QUINCE"}, t = "Pyramus, you begin: when you have spoken your speech, enter into that brake; and so everyone according to his cue." },
    { d = "Enter Puck behind" },
    { r = {"PUCK"}, t = "What hempen homespuns have we swaggering here," },
    { r = {"PUCK"}, t = "So near the cradle of the Fairy Queen?" },
    { r = {"PUCK"}, t = "What, a play toward? I’ll be an auditor;" },
    { r = {"PUCK"}, t = "An actor too perhaps, if I see cause." },
    { r = {"QUINCE"}, t = "Speak, Pyramus.—Thisbe, stand forth." },
    { r = {"PYRAMUS"}, t = "Thisbe, the flowers of odious savours sweet" },
    { r = {"QUINCE"}, t = "Odours, odours." },
    { r = {"PYRAMUS"}, t = ". . . odours savours sweet." },
    { r = {"PYRAMUS"}, t = "So hath thy breath, my dearest Thisbe dear." },
    { r = {"PYRAMUS"}, t = "But hark, a voice! Stay thou but here awhile," },
    { r = {"PYRAMUS"}, t = "And by and by I will to thee appear." },
    { d = "Exit" },
    { r = {"PUCK"}, t = "A stranger Pyramus than e’er played here!" },
    { d = "Exit" },
    { r = {"THISBE"}, t = "Must I speak now?" },
    { r = {"QUINCE"}, t = "Ay, marry, must you, For you must understand he goes but to see a noise that he heard, and is to come again." },
    { r = {"THISBE"}, t = "Most radiant Pyramus, most lily-white of hue," },
    { r = {"THISBE"}, t = "Of colour like the red rose on triumphant brier," },
    { r = {"THISBE"}, t = "Most brisky juvenal, and eke most lovely Jew," },
    { r = {"THISBE"}, t = "As true as truest horse, that yet would never tire," },
    { r = {"THISBE"}, t = "I’ll meet thee, Pyramus, at Ninny’s tomb." },
    { r = {"QUINCE"}, t = "Ninus’ tomb, man!" },
    { r = {"QUINCE"}, t = "Why, you must not speak that yet." },
    { r = {"QUINCE"}, t = "That you answer to Pyramus." },
    { r = {"QUINCE"}, t = "You speak all your part at once, cues, and all.—Pyramus enter!" },
    { r = {"QUINCE"}, t = "Your cue is past; it is ‘never tire.’" },
    { r = {"THISBE"}, t = "O, As true as truest horse, that yet would never tire." },
    { d = "Enter Puck and Bottom with an ass’s head" },
    { r = {"PYRAMUS"}, t = "If I were fair, Thisbe, I were only thine." },
    { r = {"QUINCE"}, t = "O monstrous! O strange! We are haunted. Pray, masters, fly, masters!" },
    { r = {"QUINCE"}, t = "Help!" },
    { d = "Exeunt Clowns" },
    { r = {"PUCK"}, t = "I’ll follow you. I’ll lead you about a round," },
    { r = {"PUCK"}, t = "Through bog, through bush, through brake, through brier;" },
    { r = {"PUCK"}, t = "Sometime a horse I’ll be, sometime a hound," },
    { r = {"PUCK"}, t = "A hog, a headless bear, sometime a fire;" },
    { r = {"PUCK"}, t = "And neigh, and bark, and grunt, and roar, and burn," },
    { r = {"PUCK"}, t = "Like horse, hound, hog, bear, fire, at every turn." },
    { d = "Exit" },
    { r = {"BOTTOM"}, t = "Why do they run away? This is a knavery of them to make me afeard." },
    { d = "Enter Snout" },
    { r = {"BOTTOM"}, t = "SNOUT" },
    { r = {"BOTTOM"}, t = "O Bottom, thou art changed! What do I see on thee?" },
    { r = {"BOTTOM"}, t = "What do you see? You see an ass-head of your own, do you?" },
    { d = "Exit Snout" },
    { d = "Enter Quince" },
    { r = {"QUINCE"}, t = "Bless thee, Bottom! bless thee! Thou art translated." },
    { d = "Exit" },
    { r = {"BOTTOM"}, t = "I see their knavery." },
    { r = {"BOTTOM"}, t = "This is to make an ass of me, to fright me, if they could." },
    { r = {"BOTTOM"}, t = "But I will not stir from this place, do what they can." },
    { r = {"BOTTOM"}, t = "I will walk up and down here, and I will sing, that they shall hear I am not afraid." },
    { r = {"BOTTOM"}, t = "The ousel cock, so black of hue,", d = "Sings" },
    { r = {"BOTTOM"}, t = "With orange-tawny bill," },
    { r = {"BOTTOM"}, t = "The throstle with his note so true," },
    { r = {"BOTTOM"}, t = "The wren with little quill." },
    { r = {"TITANIA"}, t = "What angel wakes me from my flowery bed?", d = "Waking", e = "/stand" },
    { r = {"BOTTOM"}, t = "The finch, the sparrow, and the lark,", d = "Sings" },
    { r = {"BOTTOM"}, t = "The plain-song cuckoo gray," },
    { r = {"BOTTOM"}, t = "Whose note full many a man doth mark," },
    { r = {"BOTTOM"}, t = "And dares not answer nay. for, indeed, who would set his wit to so foolish a bird?" },
    { r = {"BOTTOM"}, t = "Who would give a bird the lie, though he cry ‘cuckoo’ never so?" },
    { r = {"TITANIA"}, t = "I pray thee, gentle mortal, sing again." },
    { r = {"TITANIA"}, t = "Mine ear is much enamour’d of thy note." },
    { r = {"TITANIA"}, t = "So is mine eye enthrallèd to thy shape;" },
    { r = {"TITANIA"}, t = "And thy fair virtue’s force perforce doth move me," },
    { r = {"TITANIA"}, t = "On the first view, to say, to swear, I love thee." },
    { r = {"BOTTOM"}, t = "Methinks, mistress, you should have little reason for that." },
    { r = {"BOTTOM"}, t = "And yet, to say the truth, reason and love keep little company together nowadays." },
    { r = {"BOTTOM"}, t = "The more the pity that some honest neighbours will not make them friends." },
    { r = {"BOTTOM"}, t = "Nay, I can gleek upon occasion." },
    { r = {"TITANIA"}, t = "Thou art as wise as thou art beautiful." },
    { r = {"BOTTOM"}, t = "Not so, neither; but if I had wit enough to get out of this wood, I have enough to serve mine own turn." },
    { r = {"TITANIA"}, t = "Out of this wood do not desire to go." },
    { r = {"TITANIA"}, t = "Thou shalt remain here whether thou wilt or no." },
    { r = {"TITANIA"}, t = "I am a spirit of no common rate." },
    { r = {"TITANIA"}, t = "The summer still doth tend upon my state;" },
    { r = {"TITANIA"}, t = "And I do love thee: therefore, go with me." },
    { r = {"TITANIA"}, t = "I’ll give thee fairies to attend on thee;" },
    { r = {"TITANIA"}, t = "And they shall fetch thee jewels from the deep," },
    { r = {"TITANIA"}, t = "And sing, while thou on pressèd flowers dost sleep." },
    { r = {"TITANIA"}, t = "And I will purge thy mortal grossness so" },
    { r = {"TITANIA"}, t = "That thou shalt like an airy spirit go.—" },
    { r = {"TITANIA"}, t = "Peaseblossom! Cobweb! Moth! and Mustardseed!" },
    { d = "Enter four Fairies" },
    { r = {"PEASEBLOSSOM"}, t = "Ready." },
    { r = {"COBWEB"}, t = "And I." },
    { r = {"MOTH"}, t = "And I." },
    { r = {"MUSTARDSEED"}, t = "And I." },
    { r = {"ALL"}, t = "Where shall we go?" },
    { r = {"TITANIA"}, t = "Be kind and courteous to this gentleman;" },
    { r = {"TITANIA"}, t = "Hop in his walks and gambol in his eyes;" },
    { r = {"TITANIA"}, t = "Feed him with apricocks and dewberries," },
    { r = {"TITANIA"}, t = "With purple grapes, green figs, and mulberries;" },
    { r = {"TITANIA"}, t = "The honey-bags steal from the humble-bees," },
    { r = {"TITANIA"}, t = "And for night-tapers, crop their waxen thighs," },
    { r = {"TITANIA"}, t = "And light them at the fiery glow-worm’s eyes," },
    { r = {"TITANIA"}, t = "To have my love to bed and to arise;" },
    { r = {"TITANIA"}, t = "And pluck the wings from painted butterflies," },
    { r = {"TITANIA"}, t = "To fan the moonbeams from his sleeping eyes." },
    { r = {"TITANIA"}, t = "Nod to him, elves, and do him courtesies." },
    { r = {"PEASEBLOSSOM"}, t = "Hail, mortal!" },
    { r = {"COBWEB"}, t = "Hail!" },
    { r = {"MOTH"}, t = "Hail!" },
    { r = {"MUSTARDSEED"}, t = "Hail!" },
    { r = {"BOTTOM"}, t = "I cry your worships mercy, heartily.—I beseech your worship’s name." },
    { r = {"COBWEB"}, t = "Cobweb." },
    { r = {"BOTTOM"}, t = "I shall desire you of more acquaintance, good Master Cobweb." },
    { r = {"BOTTOM"}, t = "If I cut my finger, I shall make bold with you.—Your name, honest gentleman?" },
    { r = {"PEASEBLOSSOM"}, t = "Peaseblossom." },
    { r = {"BOTTOM"}, t = "I pray you, commend me to Mistress Squash, your mother, and to Master Peascod, your father." },
    { r = {"BOTTOM"}, t = "Good Master Peaseblossom, I shall desire you of more acquaintance too.—Your name, I beseech you, sir?" },
    { r = {"MUSTARDSEED"}, t = "Mustardseed." },
    { r = {"BOTTOM"}, t = "Good Master Mustardseed, I know your patience well." },
    { r = {"BOTTOM"}, t = "That same cowardly giant-like ox-beef hath devoured many a gentleman of your house." },
    { r = {"BOTTOM"}, t = "I promise you, your kindred hath made my eyes water ere now." },
    { r = {"BOTTOM"}, t = "I desire you of more acquaintance, good Master Mustardseed." },
    { r = {"TITANIA"}, t = "Come, wait upon him; lead him to my bower." },
    { r = {"TITANIA"}, t = "The moon, methinks, looks with a watery eye," },
    { r = {"TITANIA"}, t = "And when she weeps, weeps every little flower," },
    { r = {"TITANIA"}, t = "Lamenting some enforced chastity." },
    { r = {"TITANIA"}, t = "Tie up my love’s tongue, bring him silently." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 2. Another part of the wood", h = true },
    { d = "Enter Oberon" },
    { r = {"OBERON"}, t = "I wonder if Titania be awak’d;" },
    { r = {"OBERON"}, t = "Then, what it was that next came in her eye," },
    { r = {"OBERON"}, t = "Which she must dote on in extremity." },
    { d = "Enter Puck" },
    { r = {"OBERON"}, t = "Here comes my messenger. How now, mad spirit?" },
    { r = {"OBERON"}, t = "What night-rule now about this haunted grove?" },
    { r = {"PUCK"}, t = "My mistress with a monster is in love." },
    { r = {"PUCK"}, t = "Near to her close and consecrated bower," },
    { r = {"PUCK"}, t = "While she was in her dull and sleeping hour," },
    { r = {"PUCK"}, t = "A crew of patches, rude mechanicals," },
    { r = {"PUCK"}, t = "That work for bread upon Athenian stalls," },
    { r = {"PUCK"}, t = "Were met together to rehearse a play" },
    { r = {"PUCK"}, t = "Intended for great Theseus’ nuptial day." },
    { r = {"PUCK"}, t = "The shallowest thick-skin of that barren sort" },
    { r = {"PUCK"}, t = "Who Pyramus presented in their sport," },
    { r = {"PUCK"}, t = "Forsook his scene and enter’d in a brake." },
    { r = {"PUCK"}, t = "When I did him at this advantage take," },
    { r = {"PUCK"}, t = "An ass’s nole I fixed on his head." },
    { r = {"PUCK"}, t = "Anon, his Thisbe must be answerèd," },
    { r = {"PUCK"}, t = "And forth my mimic comes. When they him spy," },
    { r = {"PUCK"}, t = "As wild geese that the creeping fowler eye," },
    { r = {"PUCK"}, t = "Or russet-pated choughs, many in sort," },
    { r = {"PUCK"}, t = "Rising and cawing at the gun’s report," },
    { r = {"PUCK"}, t = "Sever themselves and madly sweep the sky," },
    { r = {"PUCK"}, t = "So at his sight away his fellows fly," },
    { r = {"PUCK"}, t = "And at our stamp, here o’er and o’er one falls;" },
    { r = {"PUCK"}, t = "He murder cries, and help from Athens calls." },
    { r = {"PUCK"}, t = "Their sense thus weak, lost with their fears, thus strong," },
    { r = {"PUCK"}, t = "Made senseless things begin to do them wrong;" },
    { r = {"PUCK"}, t = "For briers and thorns at their apparel snatch;" },
    { r = {"PUCK"}, t = "Some sleeves, some hats, from yielders all things catch." },
    { r = {"PUCK"}, t = "I led them on in this distracted fear," },
    { r = {"PUCK"}, t = "And left sweet Pyramus translated there." },
    { r = {"PUCK"}, t = "When in that moment, so it came to pass," },
    { r = {"PUCK"}, t = "Titania wak’d, and straightway lov’d an ass." },
    { r = {"OBERON"}, t = "This falls out better than I could devise." },
    { r = {"OBERON"}, t = "But hast thou yet latch’d the Athenian’s eyes" },
    { r = {"OBERON"}, t = "With the love-juice, as I did bid thee do?" },
    { r = {"PUCK"}, t = "I took him sleeping—that is finish’d too—" },
    { r = {"PUCK"}, t = "And the Athenian woman by his side," },
    { r = {"PUCK"}, t = "That, when he wak’d, of force she must be ey’d." },
    { d = "Enter Demetrius and Hermia" },
    { r = {"OBERON"}, t = "Stand close. This is the same Athenian." },
    { r = {"PUCK"}, t = "This is the woman, but not this the man." },
    { r = {"DEMETRIUS"}, t = "O why rebuke you him that loves you so?" },
    { r = {"DEMETRIUS"}, t = "Lay breath so bitter on your bitter foe." },
    { r = {"HERMIA"}, t = "Now I but chide, but I should use thee worse," },
    { r = {"HERMIA"}, t = "For thou, I fear, hast given me cause to curse." },
    { r = {"HERMIA"}, t = "If thou hast slain Lysander in his sleep," },
    { r = {"HERMIA"}, t = "Being o’er shoes in blood, plunge in the deep," },
    { r = {"HERMIA"}, t = "And kill me too." },
    { r = {"HERMIA"}, t = "The sun was not so true unto the day" },
    { r = {"HERMIA"}, t = "As he to me. Would he have stol’n away" },
    { r = {"HERMIA"}, t = "From sleeping Hermia? I’ll believe as soon" },
    { r = {"HERMIA"}, t = "This whole earth may be bor’d, and that the moon" },
    { r = {"HERMIA"}, t = "May through the centre creep and so displease" },
    { r = {"HERMIA"}, t = "Her brother’s noontide with th’ Antipodes." },
    { r = {"HERMIA"}, t = "It cannot be but thou hast murder’d him." },
    { r = {"HERMIA"}, t = "So should a murderer look, so dead, so grim." },
    { r = {"DEMETRIUS"}, t = "So should the murder’d look, and so should I," },
    { r = {"DEMETRIUS"}, t = "Pierc’d through the heart with your stern cruelty." },
    { r = {"DEMETRIUS"}, t = "Yet you, the murderer, look as bright, as clear," },
    { r = {"DEMETRIUS"}, t = "As yonder Venus in her glimmering sphere." },
    { r = {"HERMIA"}, t = "What’s this to my Lysander? Where is he?" },
    { r = {"HERMIA"}, t = "Ah, good Demetrius, wilt thou give him me?" },
    { r = {"DEMETRIUS"}, t = "I had rather give his carcass to my hounds." },
    { r = {"HERMIA"}, t = "Out, dog! Out, cur! Thou driv’st me past the bounds" },
    { r = {"HERMIA"}, t = "Of maiden’s patience. Hast thou slain him, then?" },
    { r = {"HERMIA"}, t = "Henceforth be never number’d among men!" },
    { r = {"HERMIA"}, t = "O once tell true; tell true, even for my sake!" },
    { r = {"HERMIA"}, t = "Durst thou have look’d upon him, being awake," },
    { r = {"HERMIA"}, t = "And hast thou kill’d him sleeping? O brave touch!" },
    { r = {"HERMIA"}, t = "Could not a worm, an adder, do so much?" },
    { r = {"HERMIA"}, t = "An adder did it; for with doubler tongue" },
    { r = {"HERMIA"}, t = "Than thine, thou serpent, never adder stung." },
    { r = {"DEMETRIUS"}, t = "You spend your passion on a mispris’d mood:" },
    { r = {"DEMETRIUS"}, t = "I am not guilty of Lysander’s blood;" },
    { r = {"DEMETRIUS"}, t = "Nor is he dead, for aught that I can tell." },
    { r = {"HERMIA"}, t = "I pray thee, tell me then that he is well." },
    { r = {"DEMETRIUS"}, t = "And if I could, what should I get therefore?" },
    { r = {"HERMIA"}, t = "A privilege never to see me more." },
    { r = {"HERMIA"}, t = "And from thy hated presence part I so:" },
    { r = {"HERMIA"}, t = "See me no more, whether he be dead or no." },
    { d = "Exit" },
    { r = {"DEMETRIUS"}, t = "There is no following her in this fierce vein." },
    { r = {"DEMETRIUS"}, t = "Here, therefore, for a while I will remain." },
    { r = {"DEMETRIUS"}, t = "So sorrow’s heaviness doth heavier grow" },
    { r = {"DEMETRIUS"}, t = "For debt that bankrupt sleep doth sorrow owe;" },
    { r = {"DEMETRIUS"}, t = "Which now in some slight measure it will pay," },
    { r = {"DEMETRIUS"}, t = "If for his tender here I make some stay." },
    { r = {"DEMETRIUS"}, d = "Lies down", e = "/sleep" },
    { r = {"OBERON"}, t = "What hast thou done? Thou hast mistaken quite," },
    { r = {"OBERON"}, t = "And laid the love-juice on some true-love’s sight." },
    { r = {"OBERON"}, t = "Of thy misprision must perforce ensue" },
    { r = {"OBERON"}, t = "Some true love turn’d, and not a false turn’d true." },
    { r = {"PUCK"}, t = "Then fate o’er-rules, that, one man holding troth," },
    { r = {"PUCK"}, t = "A million fail, confounding oath on oath." },
    { r = {"OBERON"}, t = "About the wood go swifter than the wind," },
    { r = {"OBERON"}, t = "And Helena of Athens look thou find." },
    { r = {"OBERON"}, t = "All fancy-sick she is, and pale of cheer" },
    { r = {"OBERON"}, t = "With sighs of love, that costs the fresh blood dear." },
    { r = {"OBERON"}, t = "By some illusion see thou bring her here;" },
    { r = {"OBERON"}, t = "I’ll charm his eyes against she do appear." },
    { r = {"PUCK"}, t = "I go, I go; look how I go," },
    { r = {"PUCK"}, t = "Swifter than arrow from the Tartar’s bow." },
    { d = "Exit" },
    { r = {"OBERON"}, t = "Flower of this purple dye," },
    { r = {"OBERON"}, t = "Hit with Cupid’s archery," },
    { r = {"OBERON"}, t = "Sink in apple of his eye." },
    { r = {"OBERON"}, t = "When his love he doth espy," },
    { r = {"OBERON"}, t = "Let her shine as gloriously" },
    { r = {"OBERON"}, t = "As the Venus of the sky.—" },
    { r = {"OBERON"}, t = "When thou wak’st, if she be by," },
    { r = {"OBERON"}, t = "Beg of her for remedy." },
    { d = "Enter Puck" },
    { r = {"PUCK"}, t = "Captain of our fairy band," },
    { r = {"PUCK"}, t = "Helena is here at hand," },
    { r = {"PUCK"}, t = "And the youth mistook by me," },
    { r = {"PUCK"}, t = "Pleading for a lover’s fee." },
    { r = {"PUCK"}, t = "Shall we their fond pageant see?" },
    { r = {"PUCK"}, t = "Lord, what fools these mortals be!" },
    { r = {"OBERON"}, t = "Stand aside. The noise they make" },
    { r = {"OBERON"}, t = "Will cause Demetrius to awake." },
    { r = {"PUCK"}, t = "Then will two at once woo one." },
    { r = {"PUCK"}, t = "That must needs be sport alone;" },
    { r = {"PUCK"}, t = "And those things do best please me" },
    { r = {"PUCK"}, t = "That befall prepost’rously." },
    { d = "Enter Lysander and Helena" },
    { r = {"LYSANDER"}, t = "Why should you think that I should woo in scorn?" },
    { r = {"LYSANDER"}, t = "Scorn and derision never come in tears." },
    { r = {"LYSANDER"}, t = "Look when I vow, I weep; and vows so born," },
    { r = {"LYSANDER"}, t = "In their nativity all truth appears." },
    { r = {"LYSANDER"}, t = "How can these things in me seem scorn to you," },
    { r = {"LYSANDER"}, t = "Bearing the badge of faith, to prove them true?" },
    { r = {"HELENA"}, t = "You do advance your cunning more and more." },
    { r = {"HELENA"}, t = "When truth kills truth, O devilish-holy fray!" },
    { r = {"HELENA"}, t = "These vows are Hermia’s: will you give her o’er?" },
    { r = {"HELENA"}, t = "Weigh oath with oath, and you will nothing weigh:" },
    { r = {"HELENA"}, t = "Your vows to her and me, put in two scales," },
    { r = {"HELENA"}, t = "Will even weigh; and both as light as tales." },
    { r = {"LYSANDER"}, t = "I had no judgment when to her I swore." },
    { r = {"HELENA"}, t = "Nor none, in my mind, now you give her o’er." },
    { r = {"LYSANDER"}, t = "Demetrius loves her, and he loves not you." },
    { r = {"DEMETRIUS"}, t = "O Helen, goddess, nymph, perfect, divine!", d = "Waking", e = "/stand" },
    { r = {"DEMETRIUS"}, t = "To what, my love, shall I compare thine eyne?" },
    { r = {"DEMETRIUS"}, t = "Crystal is muddy. O how ripe in show" },
    { r = {"DEMETRIUS"}, t = "Thy lips, those kissing cherries, tempting grow!" },
    { r = {"DEMETRIUS"}, t = "That pure congealèd white, high Taurus’ snow," },
    { r = {"DEMETRIUS"}, t = "Fann’d with the eastern wind, turns to a crow" },
    { r = {"DEMETRIUS"}, t = "When thou hold’st up thy hand. O, let me kiss" },
    { r = {"DEMETRIUS"}, t = "This princess of pure white, this seal of bliss!" },
    { r = {"HELENA"}, t = "O spite! O hell! I see you all are bent" },
    { r = {"HELENA"}, t = "To set against me for your merriment." },
    { r = {"HELENA"}, t = "If you were civil, and knew courtesy," },
    { r = {"HELENA"}, t = "You would not do me thus much injury." },
    { r = {"HELENA"}, t = "Can you not hate me, as I know you do," },
    { r = {"HELENA"}, t = "But you must join in souls to mock me too?" },
    { r = {"HELENA"}, t = "If you were men, as men you are in show," },
    { r = {"HELENA"}, t = "You would not use a gentle lady so;" },
    { r = {"HELENA"}, t = "To vow, and swear, and superpraise my parts," },
    { r = {"HELENA"}, t = "When I am sure you hate me with your hearts." },
    { r = {"HELENA"}, t = "You both are rivals, and love Hermia;" },
    { r = {"HELENA"}, t = "And now both rivals, to mock Helena." },
    { r = {"HELENA"}, t = "A trim exploit, a manly enterprise," },
    { r = {"HELENA"}, t = "To conjure tears up in a poor maid’s eyes" },
    { r = {"HELENA"}, t = "With your derision! None of noble sort" },
    { r = {"HELENA"}, t = "Would so offend a virgin, and extort" },
    { r = {"HELENA"}, t = "A poor soul’s patience, all to make you sport." },
    { r = {"LYSANDER"}, t = "You are unkind, Demetrius; be not so," },
    { r = {"LYSANDER"}, t = "For you love Hermia; this you know I know." },
    { r = {"LYSANDER"}, t = "And here, with all good will, with all my heart," },
    { r = {"LYSANDER"}, t = "In Hermia’s love I yield you up my part;" },
    { r = {"LYSANDER"}, t = "And yours of Helena to me bequeath," },
    { r = {"LYSANDER"}, t = "Whom I do love and will do till my death." },
    { r = {"HELENA"}, t = "Never did mockers waste more idle breath." },
    { r = {"DEMETRIUS"}, t = "Lysander, keep thy Hermia; I will none." },
    { r = {"DEMETRIUS"}, t = "If e’er I lov’d her, all that love is gone." },
    { r = {"DEMETRIUS"}, t = "My heart to her but as guest-wise sojourn’d;" },
    { r = {"DEMETRIUS"}, t = "And now to Helen is it home return’d," },
    { r = {"DEMETRIUS"}, t = "There to remain." },
    { r = {"LYSANDER"}, t = "Helen, it is not so." },
    { r = {"DEMETRIUS"}, t = "Disparage not the faith thou dost not know," },
    { r = {"DEMETRIUS"}, t = "Lest to thy peril thou aby it dear." },
    { r = {"DEMETRIUS"}, t = "Look where thy love comes; yonder is thy dear." },
    { d = "Enter Hermia" },
    { r = {"HERMIA"}, t = "Dark night, that from the eye his function takes," },
    { r = {"HERMIA"}, t = "The ear more quick of apprehension makes;" },
    { r = {"HERMIA"}, t = "Wherein it doth impair the seeing sense," },
    { r = {"HERMIA"}, t = "It pays the hearing double recompense." },
    { r = {"HERMIA"}, t = "Thou art not by mine eye, Lysander, found;" },
    { r = {"HERMIA"}, t = "Mine ear, I thank it, brought me to thy sound." },
    { r = {"HERMIA"}, t = "But why unkindly didst thou leave me so?" },
    { r = {"LYSANDER"}, t = "Why should he stay whom love doth press to go?" },
    { r = {"HERMIA"}, t = "What love could press Lysander from my side?" },
    { r = {"LYSANDER"}, t = "Lysander’s love, that would not let him bide," },
    { r = {"LYSANDER"}, t = "Fair Helena, who more engilds the night" },
    { r = {"LYSANDER"}, t = "Than all yon fiery oes and eyes of light." },
    { r = {"LYSANDER"}, t = "Why seek’st thou me? Could not this make thee know" },
    { r = {"LYSANDER"}, t = "The hate I bare thee made me leave thee so?" },
    { r = {"HERMIA"}, t = "You speak not as you think; it cannot be." },
    { r = {"HELENA"}, t = "Lo, she is one of this confederacy!" },
    { r = {"HELENA"}, t = "Now I perceive they have conjoin’d all three" },
    { r = {"HELENA"}, t = "To fashion this false sport in spite of me." },
    { r = {"HELENA"}, t = "Injurious Hermia, most ungrateful maid!" },
    { r = {"HELENA"}, t = "Have you conspir’d, have you with these contriv’d," },
    { r = {"HELENA"}, t = "To bait me with this foul derision?" },
    { r = {"HELENA"}, t = "Is all the counsel that we two have shar’d," },
    { r = {"HELENA"}, t = "The sisters’ vows, the hours that we have spent," },
    { r = {"HELENA"}, t = "When we have chid the hasty-footed time" },
    { r = {"HELENA"}, t = "For parting us—O, is all forgot?" },
    { r = {"HELENA"}, t = "All school-days’ friendship, childhood innocence?" },
    { r = {"HELENA"}, t = "We, Hermia, like two artificial gods," },
    { r = {"HELENA"}, t = "Have with our needles created both one flower," },
    { r = {"HELENA"}, t = "Both on one sampler, sitting on one cushion," },
    { r = {"HELENA"}, t = "Both warbling of one song, both in one key," },
    { r = {"HELENA"}, t = "As if our hands, our sides, voices, and minds," },
    { r = {"HELENA"}, t = "Had been incorporate. So we grew together," },
    { r = {"HELENA"}, t = "Like to a double cherry, seeming parted," },
    { r = {"HELENA"}, t = "But yet a union in partition," },
    { r = {"HELENA"}, t = "Two lovely berries moulded on one stem;" },
    { r = {"HELENA"}, t = "So, with two seeming bodies, but one heart;" },
    { r = {"HELENA"}, t = "Two of the first, like coats in heraldry," },
    { r = {"HELENA"}, t = "Due but to one, and crownèd with one crest." },
    { r = {"HELENA"}, t = "And will you rent our ancient love asunder," },
    { r = {"HELENA"}, t = "To join with men in scorning your poor friend?" },
    { r = {"HELENA"}, t = "It is not friendly, ’tis not maidenly." },
    { r = {"HELENA"}, t = "Our sex, as well as I, may chide you for it," },
    { r = {"HELENA"}, t = "Though I alone do feel the injury." },
    { r = {"HERMIA"}, t = "I am amazèd at your passionate words:" },
    { r = {"HERMIA"}, t = "I scorn you not; it seems that you scorn me." },
    { r = {"HELENA"}, t = "Have you not set Lysander, as in scorn," },
    { r = {"HELENA"}, t = "To follow me, and praise my eyes and face?" },
    { r = {"HELENA"}, t = "And made your other love, Demetrius," },
    { r = {"HELENA"}, t = "Who even but now did spurn me with his foot," },
    { r = {"HELENA"}, t = "To call me goddess, nymph, divine and rare," },
    { r = {"HELENA"}, t = "Precious, celestial? Wherefore speaks he this" },
    { r = {"HELENA"}, t = "To her he hates? And wherefore doth Lysander" },
    { r = {"HELENA"}, t = "Deny your love, so rich within his soul," },
    { r = {"HELENA"}, t = "And tender me, forsooth, affection," },
    { r = {"HELENA"}, t = "But by your setting on, by your consent?" },
    { r = {"HELENA"}, t = "What though I be not so in grace as you," },
    { r = {"HELENA"}, t = "So hung upon with love, so fortunate," },
    { r = {"HELENA"}, t = "But miserable most, to love unlov’d?" },
    { r = {"HELENA"}, t = "This you should pity rather than despise." },
    { r = {"HERMIA"}, t = "I understand not what you mean by this." },
    { r = {"HELENA"}, t = "Ay, do. Persever, counterfeit sad looks," },
    { r = {"HELENA"}, t = "Make mouths upon me when I turn my back," },
    { r = {"HELENA"}, t = "Wink each at other; hold the sweet jest up." },
    { r = {"HELENA"}, t = "This sport, well carried, shall be chronicled." },
    { r = {"HELENA"}, t = "If you have any pity, grace, or manners," },
    { r = {"HELENA"}, t = "You would not make me such an argument." },
    { r = {"HELENA"}, t = "But fare ye well. ’Tis partly my own fault," },
    { r = {"HELENA"}, t = "Which death, or absence, soon shall remedy." },
    { r = {"LYSANDER"}, t = "Stay, gentle Helena; hear my excuse;" },
    { r = {"LYSANDER"}, t = "My love, my life, my soul, fair Helena!" },
    { r = {"HELENA"}, t = "O excellent!" },
    { r = {"HERMIA"}, t = "Sweet, do not scorn her so." },
    { r = {"DEMETRIUS"}, t = "If she cannot entreat, I can compel." },
    { r = {"LYSANDER"}, t = "Thou canst compel no more than she entreat;" },
    { r = {"LYSANDER"}, t = "Thy threats have no more strength than her weak prayers." },
    { r = {"LYSANDER"}, t = "Helen, I love thee, by my life I do;" },
    { r = {"LYSANDER"}, t = "I swear by that which I will lose for thee" },
    { r = {"LYSANDER"}, t = "To prove him false that says I love thee not." },
    { r = {"DEMETRIUS"}, t = "I say I love thee more than he can do." },
    { r = {"LYSANDER"}, t = "If thou say so, withdraw, and prove it too." },
    { r = {"DEMETRIUS"}, t = "Quick, come." },
    { r = {"HERMIA"}, t = "Lysander, whereto tends all this?" },
    { r = {"LYSANDER"}, t = "Away, you Ethiope!" },
    { r = {"DEMETRIUS"}, t = "No, no. He will" },
    { r = {"DEMETRIUS"}, t = "Seem to break loose. Take on as you would follow," },
    { r = {"DEMETRIUS"}, t = "But yet come not. You are a tame man, go!" },
    { r = {"LYSANDER"}, t = "Hang off, thou cat, thou burr! Vile thing, let loose," },
    { r = {"LYSANDER"}, t = "Or I will shake thee from me like a serpent." },
    { r = {"HERMIA"}, t = "Why are you grown so rude? What change is this," },
    { r = {"HERMIA"}, t = "Sweet love?" },
    { r = {"LYSANDER"}, t = "Thy love? Out, tawny Tartar, out!" },
    { r = {"LYSANDER"}, t = "Out, loathèd medicine! O hated potion, hence!" },
    { r = {"HERMIA"}, t = "Do you not jest?" },
    { r = {"HELENA"}, t = "Yes, sooth, and so do you." },
    { r = {"LYSANDER"}, t = "Demetrius, I will keep my word with thee." },
    { r = {"DEMETRIUS"}, t = "I would I had your bond; for I perceive" },
    { r = {"DEMETRIUS"}, t = "A weak bond holds you; I’ll not trust your word." },
    { r = {"LYSANDER"}, t = "What, should I hurt her, strike her, kill her dead?" },
    { r = {"LYSANDER"}, t = "Although I hate her, I’ll not harm her so." },
    { r = {"HERMIA"}, t = "What, can you do me greater harm than hate?" },
    { r = {"HERMIA"}, t = "Hate me? Wherefore? O me! what news, my love?" },
    { r = {"HERMIA"}, t = "Am not I Hermia? Are not you Lysander?" },
    { r = {"HERMIA"}, t = "I am as fair now as I was erewhile." },
    { r = {"HERMIA"}, t = "Since night you lov’d me; yet since night you left me." },
    { r = {"HERMIA"}, t = "Why then, you left me—O, the gods forbid!—" },
    { r = {"HERMIA"}, t = "In earnest, shall I say?" },
    { r = {"LYSANDER"}, t = "Ay, by my life;" },
    { r = {"LYSANDER"}, t = "And never did desire to see thee more." },
    { r = {"LYSANDER"}, t = "Therefore be out of hope, of question, of doubt;" },
    { r = {"LYSANDER"}, t = "Be certain, nothing truer; ’tis no jest" },
    { r = {"LYSANDER"}, t = "That I do hate thee and love Helena." },
    { r = {"HERMIA"}, t = "O me! You juggler! You cankerblossom!" },
    { r = {"HERMIA"}, t = "You thief of love! What! have you come by night" },
    { r = {"HERMIA"}, t = "And stol’n my love’s heart from him?" },
    { r = {"HELENA"}, t = "Fine, i’ faith!" },
    { r = {"HELENA"}, t = "Have you no modesty, no maiden shame," },
    { r = {"HELENA"}, t = "No touch of bashfulness? What, will you tear" },
    { r = {"HELENA"}, t = "Impatient answers from my gentle tongue?" },
    { r = {"HELENA"}, t = "Fie, fie, you counterfeit, you puppet, you!" },
    { r = {"HERMIA"}, t = "Puppet! Why so? Ay, that way goes the game." },
    { r = {"HERMIA"}, t = "Now I perceive that she hath made compare" },
    { r = {"HERMIA"}, t = "Between our statures; she hath urg’d her height;" },
    { r = {"HERMIA"}, t = "And with her personage, her tall personage," },
    { r = {"HERMIA"}, t = "Her height, forsooth, she hath prevail’d with him." },
    { r = {"HERMIA"}, t = "And are you grown so high in his esteem" },
    { r = {"HERMIA"}, t = "Because I am so dwarfish and so low?" },
    { r = {"HERMIA"}, t = "How low am I, thou painted maypole? Speak," },
    { r = {"HERMIA"}, t = "How low am I? I am not yet so low" },
    { r = {"HERMIA"}, t = "But that my nails can reach unto thine eyes." },
    { r = {"HELENA"}, t = "I pray you, though you mock me, gentlemen," },
    { r = {"HELENA"}, t = "Let her not hurt me. I was never curst;" },
    { r = {"HELENA"}, t = "I have no gift at all in shrewishness;" },
    { r = {"HELENA"}, t = "I am a right maid for my cowardice;" },
    { r = {"HELENA"}, t = "Let her not strike me. You perhaps may think," },
    { r = {"HELENA"}, t = "Because she is something lower than myself," },
    { r = {"HELENA"}, t = "That I can match her." },
    { r = {"HERMIA"}, t = "Lower! Hark, again." },
    { r = {"HELENA"}, t = "Good Hermia, do not be so bitter with me." },
    { r = {"HELENA"}, t = "I evermore did love you, Hermia," },
    { r = {"HELENA"}, t = "Did ever keep your counsels, never wrong’d you," },
    { r = {"HELENA"}, t = "Save that, in love unto Demetrius," },
    { r = {"HELENA"}, t = "I told him of your stealth unto this wood." },
    { r = {"HELENA"}, t = "He follow’d you; for love I follow’d him;" },
    { r = {"HELENA"}, t = "But he hath chid me hence, and threaten’d me" },
    { r = {"HELENA"}, t = "To strike me, spurn me, nay, to kill me too:" },
    { r = {"HELENA"}, t = "And now, so you will let me quiet go," },
    { r = {"HELENA"}, t = "To Athens will I bear my folly back," },
    { r = {"HELENA"}, t = "And follow you no further. Let me go:" },
    { r = {"HELENA"}, t = "You see how simple and how fond I am." },
    { r = {"HERMIA"}, t = "Why, get you gone. Who is’t that hinders you?" },
    { r = {"HELENA"}, t = "A foolish heart that I leave here behind." },
    { r = {"HERMIA"}, t = "What! with Lysander?" },
    { r = {"HELENA"}, t = "With Demetrius." },
    { r = {"LYSANDER"}, t = "Be not afraid; she shall not harm thee, Helena." },
    { r = {"DEMETRIUS"}, t = "No, sir, she shall not, though you take her part." },
    { r = {"HELENA"}, t = "O, when she’s angry, she is keen and shrewd." },
    { r = {"HELENA"}, t = "She was a vixen when she went to school," },
    { r = {"HELENA"}, t = "And though she be but little, she is fierce." },
    { r = {"HERMIA"}, t = "Little again! Nothing but low and little?" },
    { r = {"HERMIA"}, t = "Why will you suffer her to flout me thus?" },
    { r = {"HERMIA"}, t = "Let me come to her." },
    { r = {"LYSANDER"}, t = "Get you gone, you dwarf;" },
    { r = {"LYSANDER"}, t = "You minimus, of hind’ring knot-grass made;" },
    { r = {"LYSANDER"}, t = "You bead, you acorn." },
    { r = {"DEMETRIUS"}, t = "You are too officious" },
    { r = {"DEMETRIUS"}, t = "In her behalf that scorns your services." },
    { r = {"DEMETRIUS"}, t = "Let her alone. Speak not of Helena;" },
    { r = {"DEMETRIUS"}, t = "Take not her part; for if thou dost intend" },
    { r = {"DEMETRIUS"}, t = "Never so little show of love to her," },
    { r = {"DEMETRIUS"}, t = "Thou shalt aby it." },
    { r = {"LYSANDER"}, t = "Now she holds me not." },
    { r = {"LYSANDER"}, t = "Now follow, if thou dar’st, to try whose right," },
    { r = {"LYSANDER"}, t = "Of thine or mine, is most in Helena." },
    { r = {"DEMETRIUS"}, t = "Follow! Nay, I’ll go with thee, cheek by jole." },
    { d = "Exeunt Lysander and Demetrius" },
    { r = {"HERMIA"}, t = "You, mistress, all this coil is long of you." },
    { r = {"HERMIA"}, t = "Nay, go not back." },
    { r = {"HELENA"}, t = "I will not trust you, I," },
    { r = {"HELENA"}, t = "Nor longer stay in your curst company." },
    { r = {"HELENA"}, t = "Your hands than mine are quicker for a fray." },
    { r = {"HELENA"}, t = "My legs are longer though, to run away." },
    { d = "Exit" },
    { r = {"HERMIA"}, t = "I am amaz’d, and know not what to say." },
    { d = "Exit, pursuing Helena" },
    { r = {"OBERON"}, t = "This is thy negligence: still thou mistak’st," },
    { r = {"OBERON"}, t = "Or else commit’st thy knaveries willfully." },
    { r = {"PUCK"}, t = "Believe me, king of shadows, I mistook." },
    { r = {"PUCK"}, t = "Did not you tell me I should know the man" },
    { r = {"PUCK"}, t = "By the Athenian garments he had on?" },
    { r = {"PUCK"}, t = "And so far blameless proves my enterprise" },
    { r = {"PUCK"}, t = "That I have ’nointed an Athenian’s eyes:" },
    { r = {"PUCK"}, t = "And so far am I glad it so did sort," },
    { r = {"PUCK"}, t = "As this their jangling I esteem a sport." },
    { r = {"OBERON"}, t = "Thou seest these lovers seek a place to fight." },
    { r = {"OBERON"}, t = "Hie therefore, Robin, overcast the night;" },
    { r = {"OBERON"}, t = "The starry welkin cover thou anon" },
    { r = {"OBERON"}, t = "With drooping fog, as black as Acheron," },
    { r = {"OBERON"}, t = "And lead these testy rivals so astray" },
    { r = {"OBERON"}, t = "As one come not within another’s way." },
    { r = {"OBERON"}, t = "Like to Lysander sometime frame thy tongue," },
    { r = {"OBERON"}, t = "Then stir Demetrius up with bitter wrong;" },
    { r = {"OBERON"}, t = "And sometime rail thou like Demetrius." },
    { r = {"OBERON"}, t = "And from each other look thou lead them thus," },
    { r = {"OBERON"}, t = "Till o’er their brows death-counterfeiting sleep" },
    { r = {"OBERON"}, t = "With leaden legs and batty wings doth creep." },
    { r = {"OBERON"}, t = "Then crush this herb into Lysander’s eye," },
    { r = {"OBERON"}, t = "Whose liquor hath this virtuous property," },
    { r = {"OBERON"}, t = "To take from thence all error with his might" },
    { r = {"OBERON"}, t = "And make his eyeballs roll with wonted sight." },
    { r = {"OBERON"}, t = "When they next wake, all this derision" },
    { r = {"OBERON"}, t = "Shall seem a dream and fruitless vision;" },
    { r = {"OBERON"}, t = "And back to Athens shall the lovers wend," },
    { r = {"OBERON"}, t = "With league whose date till death shall never end." },
    { r = {"OBERON"}, t = "Whiles I in this affair do thee employ," },
    { r = {"OBERON"}, t = "I’ll to my queen, and beg her Indian boy;" },
    { r = {"OBERON"}, t = "And then I will her charmèd eye release" },
    { r = {"OBERON"}, t = "From monster’s view, and all things shall be peace." },
    { r = {"PUCK"}, t = "My fairy lord, this must be done with haste," },
    { r = {"PUCK"}, t = "For night’s swift dragons cut the clouds full fast;" },
    { r = {"PUCK"}, t = "And yonder shines Aurora’s harbinger," },
    { r = {"PUCK"}, t = "At whose approach, ghosts wandering here and there" },
    { r = {"PUCK"}, t = "Troop home to churchyards. Damnèd spirits all," },
    { r = {"PUCK"}, t = "That in cross-ways and floods have burial," },
    { r = {"PUCK"}, t = "Already to their wormy beds are gone;" },
    { r = {"PUCK"}, t = "For fear lest day should look their shames upon," },
    { r = {"PUCK"}, t = "They wilfully themselves exile from light," },
    { r = {"PUCK"}, t = "And must for aye consort with black-brow’d night." },
    { r = {"OBERON"}, t = "But we are spirits of another sort:" },
    { r = {"OBERON"}, t = "I with the morning’s love have oft made sport;" },
    { r = {"OBERON"}, t = "And, like a forester, the groves may tread" },
    { r = {"OBERON"}, t = "Even till the eastern gate, all fiery-red," },
    { r = {"OBERON"}, t = "Opening on Neptune with fair blessèd beams," },
    { r = {"OBERON"}, t = "Turns into yellow gold his salt-green streams." },
    { r = {"OBERON"}, t = "But, notwithstanding, haste, make no delay." },
    { r = {"OBERON"}, t = "We may effect this business yet ere day." },
    { d = "Exit Oberon" },
    { r = {"PUCK"}, t = "Up and down, up and down," },
    { r = {"PUCK"}, t = "I will lead them up and down." },
    { r = {"PUCK"}, t = "I am fear’d in field and town." },
    { r = {"PUCK"}, t = "Goblin, lead them up and down." },
    { r = {"PUCK"}, t = "Here comes one." },
    { d = "Enter Lysander" },
    { r = {"LYSANDER"}, t = "Where art thou, proud Demetrius? Speak thou now." },
    { r = {"PUCK"}, t = "Here, villain, drawn and ready. Where art thou?" },
    { r = {"LYSANDER"}, t = "I will be with thee straight." },
    { r = {"PUCK"}, t = "Follow me then to plainer ground." },
    { d = "Exit Lysander as following the voice" },
    { d = "Enter Demetrius" },
    { r = {"DEMETRIUS"}, t = "Lysander, speak again." },
    { r = {"DEMETRIUS"}, t = "Thou runaway, thou coward, art thou fled?" },
    { r = {"DEMETRIUS"}, t = "Speak. In some bush? Where dost thou hide thy head?" },
    { r = {"PUCK"}, t = "Thou coward, art thou bragging to the stars," },
    { r = {"PUCK"}, t = "Telling the bushes that thou look’st for wars," },
    { r = {"PUCK"}, t = "And wilt not come? Come, recreant, come, thou child!" },
    { r = {"PUCK"}, t = "I’ll whip thee with a rod. He is defil’d" },
    { r = {"PUCK"}, t = "That draws a sword on thee." },
    { r = {"DEMETRIUS"}, t = "Yea, art thou there?" },
    { r = {"PUCK"}, t = "Follow my voice; we’ll try no manhood here." },
    { d = "Exeunt" },
    { d = "Enter Lysander" },
    { r = {"LYSANDER"}, t = "He goes before me, and still dares me on;" },
    { r = {"LYSANDER"}, t = "When I come where he calls, then he is gone." },
    { r = {"LYSANDER"}, t = "The villain is much lighter-heel’d than I:" },
    { r = {"LYSANDER"}, t = "I follow’d fast, but faster he did fly," },
    { r = {"LYSANDER"}, t = "That fallen am I in dark uneven way," },
    { r = {"LYSANDER"}, t = "And here will rest me.  Come, thou gentle day!" },
    { r = {"LYSANDER"}, t = "For if but once thou show me thy grey light,", d = "Lies down", e = "/sleep" },
    { r = {"LYSANDER"}, t = "I’ll find Demetrius, and revenge this spite." },
    { r = {"LYSANDER"}, d = "Sleeps", e = "/sleep" },
    { d = "Enter Puck and Demetrius" },
    { r = {"PUCK"}, t = "Ho, ho, ho! Coward, why com’st thou not?" },
    { r = {"DEMETRIUS"}, t = "Abide me, if thou dar’st; for well I wot" },
    { r = {"DEMETRIUS"}, t = "Thou runn’st before me, shifting every place," },
    { r = {"DEMETRIUS"}, t = "And dar’st not stand, nor look me in the face." },
    { r = {"DEMETRIUS"}, t = "Where art thou?" },
    { r = {"PUCK"}, t = "Come hither; I am here." },
    { r = {"DEMETRIUS"}, t = "Nay, then, thou mock’st me. Thou shalt buy this dear" },
    { r = {"DEMETRIUS"}, t = "If ever I thy face by daylight see:" },
    { r = {"DEMETRIUS"}, t = "Now go thy way. Faintness constraineth me" },
    { r = {"DEMETRIUS"}, t = "To measure out my length on this cold bed." },
    { r = {"DEMETRIUS"}, t = "By day’s approach look to be visited." },
    { r = {"DEMETRIUS"}, d = "Lies down and sleeps", e = "/sleep" },
    { d = "Enter Helena" },
    { r = {"HELENA"}, t = "O weary night, O long and tedious night," },
    { r = {"HELENA"}, t = "Abate thy hours! Shine, comforts, from the east," },
    { r = {"HELENA"}, t = "That I may back to Athens by daylight," },
    { r = {"HELENA"}, t = "From these that my poor company detest." },
    { r = {"HELENA"}, t = "And sleep, that sometimes shuts up sorrow’s eye," },
    { r = {"HELENA"}, t = "Steal me awhile from mine own company." },
    { r = {"HELENA"}, d = "Sleeps", e = "/sleep" },
    { r = {"PUCK"}, t = "Yet but three? Come one more." },
    { r = {"PUCK"}, t = "Two of both kinds makes up four." },
    { r = {"PUCK"}, t = "Here she comes, curst and sad." },
    { r = {"PUCK"}, t = "Cupid is a knavish lad" },
    { r = {"PUCK"}, t = "Thus to make poor females mad." },
    { d = "Enter Hermia" },
    { r = {"HERMIA"}, t = "Never so weary, never so in woe," },
    { r = {"HERMIA"}, t = "Bedabbled with the dew, and torn with briers," },
    { r = {"HERMIA"}, t = "I can no further crawl, no further go;" },
    { r = {"HERMIA"}, t = "My legs can keep no pace with my desires." },
    { r = {"HERMIA"}, t = "Here will I rest me till the break of day." },
    { r = {"HERMIA"}, t = "Heavens shield Lysander, if they mean a fray!" },
    { r = {"HERMIA"}, d = "Lies down", e = "/sleep" },
    { r = {"PUCK"}, t = "On the ground" },
    { r = {"PUCK"}, t = "Sleep sound." },
    { r = {"PUCK"}, t = "I’ll apply" },
    { r = {"PUCK"}, t = "To your eye," },
    { r = {"PUCK"}, t = "Gentle lover, remedy." },
    { d = "Squeezing the juice on Lysander’s eye" },
    { r = {"PUCK"}, t = "When thou wak’st," },
    { r = {"PUCK"}, t = "Thou tak’st" },
    { r = {"PUCK"}, t = "True delight" },
    { r = {"PUCK"}, t = "In the sight" },
    { r = {"PUCK"}, t = "Of thy former lady’s eye." },
    { r = {"PUCK"}, t = "And the country proverb known," },
    { r = {"PUCK"}, t = "That every man should take his own," },
    { r = {"PUCK"}, t = "In your waking shall be shown:" },
    { r = {"PUCK"}, t = "Jack shall have Jill;" },
    { r = {"PUCK"}, t = "Nought shall go ill;" },
    { r = {"PUCK"}, t = "The man shall have his mare again, and all shall be well." },
    { d = "Exit Puck" },
    { d = "Act 4, Scene 1. The Wood", h = true },
    { d = "Lysander, Demetrius, Helena and Hermia still asleep." },
    { d = "Enter Titania and Bottom; Peaseblossom, Cobweb, Moth, Mustardseed and other Fairies attending; Oberon behind, unseen" },
    { r = {"TITANIA"}, t = "Come, sit thee down upon this flowery bed," },
    { r = {"TITANIA"}, t = "While I thy amiable cheeks do coy," },
    { r = {"TITANIA"}, t = "And stick musk-roses in thy sleek smooth head," },
    { r = {"TITANIA"}, t = "And kiss thy fair large ears, my gentle joy." },
    { r = {"BOTTOM"}, t = "Where’s Peaseblossom?" },
    { r = {"PEASEBLOSSOM"}, t = "Ready." },
    { r = {"BOTTOM"}, t = "Scratch my head, Peaseblossom. Where’s Monsieur Cobweb?" },
    { r = {"COBWEB"}, t = "Ready." },
    { r = {"BOTTOM"}, t = "Monsieur Cobweb; good monsieur, get you your weapons in your hand and kill me a red-hipped humble-bee on the top of a thistle; and, good monsieur, bring me the honey-bag." },
    { r = {"BOTTOM"}, t = "Do not fret yourself too much in the action, monsieur; and, good monsieur, have a care the honey-bag break not; I would be loath to have you overflown with a honey-bag, signior." },
    { r = {"BOTTOM"}, t = "Where’s Monsieur Mustardseed?" },
    { r = {"MUSTARDSEED"}, t = "Ready." },
    { r = {"BOTTOM"}, t = "Give me your neaf, Monsieur Mustardseed." },
    { r = {"BOTTOM"}, t = "Pray you, leave your courtesy, good monsieur." },
    { r = {"MUSTARDSEED"}, t = "What’s your will?" },
    { r = {"BOTTOM"}, t = "Nothing, good monsieur, but to help Cavalery Cobweb to scratch." },
    { r = {"BOTTOM"}, t = "I must to the barber’s, monsieur, for methinks I am marvellous hairy about the face; and I am such a tender ass, if my hair do but tickle me, I must scratch." },
    { r = {"TITANIA"}, t = "What, wilt thou hear some music, my sweet love?" },
    { r = {"BOTTOM"}, t = "I have a reasonable good ear in music." },
    { r = {"BOTTOM"}, t = "Let us have the tongs and the bones." },
    { r = {"TITANIA"}, t = "Or say, sweet love, what thou desirest to eat." },
    { r = {"BOTTOM"}, t = "Truly, a peck of provender; I could munch your good dry oats." },
    { r = {"BOTTOM"}, t = "Methinks I have a great desire to a bottle of hay: good hay, sweet hay, hath no fellow." },
    { r = {"TITANIA"}, t = "I have a venturous fairy that shall seek" },
    { r = {"TITANIA"}, t = "The squirrel’s hoard, and fetch thee new nuts." },
    { r = {"BOTTOM"}, t = "I had rather have a handful or two of dried peas." },
    { r = {"BOTTOM"}, t = "But, I pray you, let none of your people stir me; I have an exposition of sleep come upon me." },
    { r = {"TITANIA"}, t = "Sleep thou, and I will wind thee in my arms." },
    { r = {"TITANIA"}, t = "Fairies, be gone, and be all ways away." },
    { r = {"TITANIA"}, t = "So doth the woodbine the sweet honeysuckle" },
    { r = {"TITANIA"}, t = "Gently entwist, the female ivy so" },
    { r = {"TITANIA"}, t = "Enrings the barky fingers of the elm." },
    { r = {"TITANIA"}, t = "O, how I love thee! How I dote on thee!" },
    { d = "They sleep" },
    { r = {"TITANIA"}, t = "Oberon advances. Enter Puck." },
    { r = {"OBERON"}, t = "Welcome, good Robin. Seest thou this sweet sight?" },
    { r = {"OBERON"}, t = "Her dotage now I do begin to pity." },
    { r = {"OBERON"}, t = "For, meeting her of late behind the wood," },
    { r = {"OBERON"}, t = "Seeking sweet favours for this hateful fool," },
    { r = {"OBERON"}, t = "I did upbraid her and fall out with her:" },
    { r = {"OBERON"}, t = "For she his hairy temples then had rounded" },
    { r = {"OBERON"}, t = "With coronet of fresh and fragrant flowers;" },
    { r = {"OBERON"}, t = "And that same dew, which sometime on the buds" },
    { r = {"OBERON"}, t = "Was wont to swell like round and orient pearls," },
    { r = {"OBERON"}, t = "Stood now within the pretty flouriets’ eyes," },
    { r = {"OBERON"}, t = "Like tears that did their own disgrace bewail." },
    { r = {"OBERON"}, t = "When I had at my pleasure taunted her," },
    { r = {"OBERON"}, t = "And she in mild terms begg’d my patience," },
    { r = {"OBERON"}, t = "I then did ask of her her changeling child;" },
    { r = {"OBERON"}, t = "Which straight she gave me, and her fairy sent" },
    { r = {"OBERON"}, t = "To bear him to my bower in fairyland." },
    { r = {"OBERON"}, t = "And now I have the boy, I will undo" },
    { r = {"OBERON"}, t = "This hateful imperfection of her eyes." },
    { r = {"OBERON"}, t = "And, gentle Puck, take this transformèd scalp" },
    { r = {"OBERON"}, t = "From off the head of this Athenian swain," },
    { r = {"OBERON"}, t = "That he awaking when the other do," },
    { r = {"OBERON"}, t = "May all to Athens back again repair," },
    { r = {"OBERON"}, t = "And think no more of this night’s accidents" },
    { r = {"OBERON"}, t = "But as the fierce vexation of a dream." },
    { r = {"OBERON"}, t = "But first I will release the Fairy Queen." },
    { d = "Touching her eyes with an herb" },
    { r = {"OBERON"}, t = "Be as thou wast wont to be;" },
    { r = {"OBERON"}, t = "See as thou was wont to see." },
    { r = {"OBERON"}, t = "Dian’s bud o’er Cupid’s flower" },
    { r = {"OBERON"}, t = "Hath such force and blessed power." },
    { r = {"OBERON"}, t = "Now, my Titania, wake you, my sweet queen." },
    { r = {"TITANIA"}, t = "My Oberon, what visions have I seen!" },
    { r = {"TITANIA"}, t = "Methought I was enamour’d of an ass." },
    { r = {"OBERON"}, t = "There lies your love." },
    { r = {"TITANIA"}, t = "How came these things to pass?" },
    { r = {"TITANIA"}, t = "O, how mine eyes do loathe his visage now!" },
    { r = {"OBERON"}, t = "Silence awhile.—Robin, take off this head." },
    { r = {"OBERON"}, t = "Titania, music call; and strike more dead" },
    { r = {"OBERON"}, t = "Than common sleep, of all these five the sense." },
    { r = {"TITANIA"}, t = "Music, ho, music, such as charmeth sleep." },
    { r = {"PUCK"}, t = "Now when thou wak’st, with thine own fool’s eyes peep." },
    { r = {"OBERON"}, t = "Sound, music." },
    { d = "Still music" },
    { r = {"OBERON"}, t = "Come, my queen, take hands with me," },
    { r = {"OBERON"}, t = "And rock the ground whereon these sleepers be." },
    { r = {"OBERON"}, t = "Now thou and I are new in amity," },
    { r = {"OBERON"}, t = "And will tomorrow midnight solemnly" },
    { r = {"OBERON"}, t = "Dance in Duke Theseus’ house triumphantly," },
    { r = {"OBERON"}, t = "And bless it to all fair prosperity:" },
    { r = {"OBERON"}, t = "There shall the pairs of faithful lovers be" },
    { r = {"OBERON"}, t = "Wedded, with Theseus, all in jollity." },
    { r = {"PUCK"}, t = "Fairy king, attend and mark." },
    { r = {"PUCK"}, t = "I do hear the morning lark." },
    { r = {"OBERON"}, t = "Then, my queen, in silence sad," },
    { r = {"OBERON"}, t = "Trip we after night’s shade." },
    { r = {"OBERON"}, t = "We the globe can compass soon," },
    { r = {"OBERON"}, t = "Swifter than the wand’ring moon." },
    { r = {"TITANIA"}, t = "Come, my lord, and in our flight," },
    { r = {"TITANIA"}, t = "Tell me how it came this night" },
    { r = {"TITANIA"}, t = "That I sleeping here was found" },
    { r = {"TITANIA"}, t = "With these mortals on the ground." },
    { d = "Exeunt. Horns sound within" },
    { d = "Enter Theseus, Hippolyta, Egeus and Train" },
    { r = {"THESEUS"}, t = "Go, one of you, find out the forester;" },
    { r = {"THESEUS"}, t = "For now our observation is perform’d;" },
    { r = {"THESEUS"}, t = "And since we have the vaward of the day," },
    { r = {"THESEUS"}, t = "My love shall hear the music of my hounds." },
    { r = {"THESEUS"}, t = "Uncouple in the western valley; let them go." },
    { r = {"THESEUS"}, t = "Dispatch I say, and find the forester." },
    { d = "Exit an Attendant" },
    { r = {"THESEUS"}, t = "We will, fair queen, up to the mountain’s top," },
    { r = {"THESEUS"}, t = "And mark the musical confusion" },
    { r = {"THESEUS"}, t = "Of hounds and echo in conjunction." },
    { r = {"HIPPOLYTA"}, t = "I was with Hercules and Cadmus once," },
    { r = {"HIPPOLYTA"}, t = "When in a wood of Crete they bay’d the bear" },
    { r = {"HIPPOLYTA"}, t = "With hounds of Sparta. Never did I hear" },
    { r = {"HIPPOLYTA"}, t = "Such gallant chiding; for, besides the groves," },
    { r = {"HIPPOLYTA"}, t = "The skies, the fountains, every region near" },
    { r = {"HIPPOLYTA"}, t = "Seem’d all one mutual cry. I never heard" },
    { r = {"HIPPOLYTA"}, t = "So musical a discord, such sweet thunder." },
    { r = {"THESEUS"}, t = "My hounds are bred out of the Spartan kind," },
    { r = {"THESEUS"}, t = "So flew’d, so sanded; and their heads are hung" },
    { r = {"THESEUS"}, t = "With ears that sweep away the morning dew;" },
    { r = {"THESEUS"}, t = "Crook-knee’d and dewlap’d like Thessalian bulls;" },
    { r = {"THESEUS"}, t = "Slow in pursuit, but match’d in mouth like bells," },
    { r = {"THESEUS"}, t = "Each under each. A cry more tuneable" },
    { r = {"THESEUS"}, t = "Was never holla’d to, nor cheer’d with horn," },
    { r = {"THESEUS"}, t = "In Crete, in Sparta, nor in Thessaly." },
    { r = {"THESEUS"}, t = "Judge when you hear.—But, soft, what nymphs are these?" },
    { r = {"EGEUS"}, t = "My lord, this is my daughter here asleep," },
    { r = {"EGEUS"}, t = "And this Lysander; this Demetrius is;" },
    { r = {"EGEUS"}, t = "This Helena, old Nedar’s Helena:" },
    { r = {"EGEUS"}, t = "I wonder of their being here together." },
    { r = {"THESEUS"}, t = "No doubt they rose up early to observe" },
    { r = {"THESEUS"}, t = "The rite of May; and, hearing our intent," },
    { r = {"THESEUS"}, t = "Came here in grace of our solemnity." },
    { r = {"THESEUS"}, t = "But speak, Egeus; is not this the day" },
    { r = {"THESEUS"}, t = "That Hermia should give answer of her choice?" },
    { r = {"EGEUS"}, t = "It is, my lord." },
    { r = {"THESEUS"}, t = "Go, bid the huntsmen wake them with their horns." },
    { r = {"THESEUS"}, t = "Horns, and shout within." },
    { r = {"THESEUS"}, t = "Demetrius, Lysander, Hermia and Helena wake and start up." },
    { r = {"THESEUS"}, t = "Good morrow, friends. Saint Valentine is past." },
    { r = {"THESEUS"}, t = "Begin these wood-birds but to couple now?" },
    { r = {"LYSANDER"}, t = "Pardon, my lord." },
    { r = {"LYSANDER"}, t = "He and the rest kneel to  Theseus." },
    { r = {"THESEUS"}, t = "I pray you all, stand up." },
    { r = {"THESEUS"}, t = "I know you two are rival enemies." },
    { r = {"THESEUS"}, t = "How comes this gentle concord in the world," },
    { r = {"THESEUS"}, t = "That hatred is so far from jealousy" },
    { r = {"THESEUS"}, t = "To sleep by hate, and fear no enmity?" },
    { r = {"LYSANDER"}, t = "My lord, I shall reply amazedly," },
    { r = {"LYSANDER"}, t = "Half sleep, half waking; but as yet, I swear," },
    { r = {"LYSANDER"}, t = "I cannot truly say how I came here." },
    { r = {"LYSANDER"}, t = "But, as I think (for truly would I speak)" },
    { r = {"LYSANDER"}, t = "And now I do bethink me, so it is:" },
    { r = {"LYSANDER"}, t = "I came with Hermia hither. Our intent" },
    { r = {"LYSANDER"}, t = "Was to be gone from Athens, where we might be" },
    { r = {"LYSANDER"}, t = "Without the peril of the Athenian law." },
    { r = {"EGEUS"}, t = "Enough, enough, my lord; you have enough." },
    { r = {"EGEUS"}, t = "I beg the law, the law upon his head." },
    { r = {"EGEUS"}, t = "They would have stol’n away, they would, Demetrius," },
    { r = {"EGEUS"}, t = "Thereby to have defeated you and me:" },
    { r = {"EGEUS"}, t = "You of your wife, and me of my consent," },
    { r = {"EGEUS"}, t = "Of my consent that she should be your wife." },
    { r = {"DEMETRIUS"}, t = "My lord, fair Helen told me of their stealth," },
    { r = {"DEMETRIUS"}, t = "Of this their purpose hither to this wood;" },
    { r = {"DEMETRIUS"}, t = "And I in fury hither follow’d them," },
    { r = {"DEMETRIUS"}, t = "Fair Helena in fancy following me." },
    { r = {"DEMETRIUS"}, t = "But, my good lord, I wot not by what power," },
    { r = {"DEMETRIUS"}, t = "(But by some power it is) my love to Hermia," },
    { r = {"DEMETRIUS"}, t = "Melted as the snow, seems to me now" },
    { r = {"DEMETRIUS"}, t = "As the remembrance of an idle gaud" },
    { r = {"DEMETRIUS"}, t = "Which in my childhood I did dote upon;" },
    { r = {"DEMETRIUS"}, t = "And all the faith, the virtue of my heart," },
    { r = {"DEMETRIUS"}, t = "The object and the pleasure of mine eye," },
    { r = {"DEMETRIUS"}, t = "Is only Helena. To her, my lord," },
    { r = {"DEMETRIUS"}, t = "Was I betroth’d ere I saw Hermia." },
    { r = {"DEMETRIUS"}, t = "But like a sickness did I loathe this food." },
    { r = {"DEMETRIUS"}, t = "But, as in health, come to my natural taste," },
    { r = {"DEMETRIUS"}, t = "Now I do wish it, love it, long for it," },
    { r = {"DEMETRIUS"}, t = "And will for evermore be true to it." },
    { r = {"THESEUS"}, t = "Fair lovers, you are fortunately met." },
    { r = {"THESEUS"}, t = "Of this discourse we more will hear anon." },
    { r = {"THESEUS"}, t = "Egeus, I will overbear your will;" },
    { r = {"THESEUS"}, t = "For in the temple, by and by with us," },
    { r = {"THESEUS"}, t = "These couples shall eternally be knit." },
    { r = {"THESEUS"}, t = "And, for the morning now is something worn," },
    { r = {"THESEUS"}, t = "Our purpos’d hunting shall be set aside." },
    { r = {"THESEUS"}, t = "Away with us to Athens. Three and three," },
    { r = {"THESEUS"}, t = "We’ll hold a feast in great solemnity." },
    { r = {"THESEUS"}, t = "Come, Hippolyta." },
    { d = "Exeunt Theseus, Hippolyta, Egeus and Train" },
    { r = {"DEMETRIUS"}, t = "These things seem small and undistinguishable," },
    { r = {"DEMETRIUS"}, t = "Like far-off mountains turnèd into clouds." },
    { r = {"HERMIA"}, t = "Methinks I see these things with parted eye," },
    { r = {"HERMIA"}, t = "When everything seems double." },
    { r = {"HELENA"}, t = "So methinks." },
    { r = {"HELENA"}, t = "And I have found Demetrius like a jewel," },
    { r = {"HELENA"}, t = "Mine own, and not mine own." },
    { r = {"DEMETRIUS"}, t = "Are you sure" },
    { r = {"DEMETRIUS"}, t = "That we are awake? It seems to me" },
    { r = {"DEMETRIUS"}, t = "That yet we sleep, we dream. Do not you think" },
    { r = {"DEMETRIUS"}, t = "The Duke was here, and bid us follow him?" },
    { r = {"HERMIA"}, t = "Yea, and my father." },
    { r = {"HELENA"}, t = "And Hippolyta." },
    { r = {"LYSANDER"}, t = "And he did bid us follow to the temple." },
    { r = {"DEMETRIUS"}, t = "Why, then, we are awake: let’s follow him," },
    { r = {"DEMETRIUS"}, t = "And by the way let us recount our dreams." },
    { d = "Exeunt" },
    { r = {"BOTTOM"}, t = "When my cue comes, call me, and I will answer. My next is", d = "Waking", e = "/stand" },
    { r = {"BOTTOM"}, t = "‘Most fair Pyramus.’ Heigh-ho! Peter Quince! Flute, the bellows-mender!" },
    { r = {"BOTTOM"}, t = "Snout, the tinker!" },
    { r = {"BOTTOM"}, t = "Starveling!" },
    { r = {"BOTTOM"}, t = "God’s my life!" },
    { r = {"BOTTOM"}, t = "Stol’n hence, and left me asleep!" },
    { r = {"BOTTOM"}, t = "I have had a most rare vision." },
    { r = {"BOTTOM"}, t = "I have had a dream, past the wit of man to say what dream it was." },
    { r = {"BOTTOM"}, t = "Man is but an ass if he go about to expound this dream." },
    { r = {"BOTTOM"}, t = "Methought I was—there is no man can tell what." },
    { r = {"BOTTOM"}, t = "Methought I was, and methought I had—but man is but a patched fool if he will offer to say what methought I had." },
    { r = {"BOTTOM"}, t = "The eye of man hath not heard, the ear of man hath not seen, man’s hand is not able to taste, his tongue to conceive, nor his heart to report, what my dream was." },
    { r = {"BOTTOM"}, t = "I will get Peter Quince to write a ballad of this dream: it shall be called ‘Bottom’s Dream’, because it hath no bottom; and I will sing it in the latter end of a play, before the Duke." },
    { r = {"BOTTOM"}, t = "Peradventure, to make it the more gracious, I shall sing it at her death." },
    { d = "Exit" },
    { d = "Act 4, Scene 2. Athens. A Room in Quince’s House", h = true },
    { d = "Enter Quince, Flute, Snout and Starveling" },
    { r = {"QUINCE"}, t = "Have you sent to Bottom’s house? Is he come home yet?" },
    { r = {"STARVELING"}, t = "He cannot be heard of. Out of doubt he is transported." },
    { r = {"FLUTE"}, t = "If he come not, then the play is marred. It goes not forward, doth it?" },
    { r = {"QUINCE"}, t = "It is not possible." },
    { r = {"QUINCE"}, t = "You have not a man in all Athens able to discharge Pyramus but he." },
    { r = {"FLUTE"}, t = "No, he hath simply the best wit of any handicraft man in Athens." },
    { r = {"QUINCE"}, t = "Yea, and the best person too, and he is a very paramour for a sweet voice." },
    { r = {"FLUTE"}, t = "You must say paragon. A paramour is, God bless us, a thing of naught." },
    { d = "Enter Snug" },
    { r = {"FLUTE"}, t = "SNUG" },
    { r = {"FLUTE"}, t = "Masters, the Duke is coming from the temple, and there is two or three lords and ladies more married." },
    { r = {"FLUTE"}, t = "If our sport had gone forward, we had all been made men." },
    { r = {"FLUTE"}, t = "O sweet bully Bottom!" },
    { r = {"FLUTE"}, t = "Thus hath he lost sixpence a day during his life; he could not have ’scaped sixpence a day." },
    { r = {"FLUTE"}, t = "An the Duke had not given him sixpence a day for playing Pyramus, I’ll be hanged." },
    { r = {"FLUTE"}, t = "He would have deserved it: sixpence a day in Pyramus, or nothing." },
    { d = "Enter Bottom" },
    { r = {"BOTTOM"}, t = "Where are these lads? Where are these hearts?" },
    { r = {"QUINCE"}, t = "Bottom! O most courageous day! O most happy hour!" },
    { r = {"BOTTOM"}, t = "Masters, I am to discourse wonders: but ask me not what; for if I tell you, I am not true Athenian." },
    { r = {"BOTTOM"}, t = "I will tell you everything, right as it fell out." },
    { r = {"QUINCE"}, t = "Let us hear, sweet Bottom." },
    { r = {"BOTTOM"}, t = "Not a word of me." },
    { r = {"BOTTOM"}, t = "All that I will tell you is, that the Duke hath dined." },
    { r = {"BOTTOM"}, t = "Get your apparel together, good strings to your beards, new ribbons to your pumps; meet presently at the palace; every man look o’er his part." },
    { r = {"BOTTOM"}, t = "For the short and the long is, our play is preferred." },
    { r = {"BOTTOM"}, t = "In any case, let Thisbe have clean linen; and let not him that plays the lion pare his nails, for they shall hang out for the lion’s claws." },
    { r = {"BOTTOM"}, t = "And most dear actors, eat no onions nor garlick, for we are to utter sweet breath; and I do not doubt but to hear them say it is a sweet comedy." },
    { r = {"BOTTOM"}, t = "No more words. Away! Go, away!" },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. Athens. An Apartment in the Palace of Theseus", h = true },
    { d = "Enter Theseus, Hippolyta, Philostrate, Lords and Attendants" },
    { r = {"HIPPOLYTA"}, t = "’Tis strange, my Theseus, that these lovers speak of." },
    { r = {"THESEUS"}, t = "More strange than true. I never may believe" },
    { r = {"THESEUS"}, t = "These antique fables, nor these fairy toys." },
    { r = {"THESEUS"}, t = "Lovers and madmen have such seething brains," },
    { r = {"THESEUS"}, t = "Such shaping fantasies, that apprehend" },
    { r = {"THESEUS"}, t = "More than cool reason ever comprehends." },
    { r = {"THESEUS"}, t = "The lunatic, the lover, and the poet" },
    { r = {"THESEUS"}, t = "Are of imagination all compact:" },
    { r = {"THESEUS"}, t = "One sees more devils than vast hell can hold;" },
    { r = {"THESEUS"}, t = "That is the madman: the lover, all as frantic," },
    { r = {"THESEUS"}, t = "Sees Helen’s beauty in a brow of Egypt:" },
    { r = {"THESEUS"}, t = "The poet’s eye, in a fine frenzy rolling," },
    { r = {"THESEUS"}, t = "Doth glance from heaven to earth, from earth to heaven;" },
    { r = {"THESEUS"}, t = "And as imagination bodies forth" },
    { r = {"THESEUS"}, t = "The forms of things unknown, the poet’s pen" },
    { r = {"THESEUS"}, t = "Turns them to shapes, and gives to airy nothing" },
    { r = {"THESEUS"}, t = "A local habitation and a name." },
    { r = {"THESEUS"}, t = "Such tricks hath strong imagination," },
    { r = {"THESEUS"}, t = "That if it would but apprehend some joy," },
    { r = {"THESEUS"}, t = "It comprehends some bringer of that joy." },
    { r = {"THESEUS"}, t = "Or in the night, imagining some fear," },
    { r = {"THESEUS"}, t = "How easy is a bush supposed a bear?" },
    { r = {"HIPPOLYTA"}, t = "But all the story of the night told over," },
    { r = {"HIPPOLYTA"}, t = "And all their minds transfigur’d so together," },
    { r = {"HIPPOLYTA"}, t = "More witnesseth than fancy’s images," },
    { r = {"HIPPOLYTA"}, t = "And grows to something of great constancy;" },
    { r = {"HIPPOLYTA"}, t = "But, howsoever, strange and admirable." },
    { d = "Enter lovers: Lysander, Demetrius, Hermia and Helena" },
    { r = {"THESEUS"}, t = "Here come the lovers, full of joy and mirth." },
    { r = {"THESEUS"}, t = "Joy, gentle friends, joy and fresh days of love" },
    { r = {"THESEUS"}, t = "Accompany your hearts!" },
    { r = {"LYSANDER"}, t = "More than to us" },
    { r = {"LYSANDER"}, t = "Wait in your royal walks, your board, your bed!" },
    { r = {"THESEUS"}, t = "Come now; what masques, what dances shall we have," },
    { r = {"THESEUS"}, t = "To wear away this long age of three hours" },
    { r = {"THESEUS"}, t = "Between our after-supper and bed-time?" },
    { r = {"THESEUS"}, t = "Where is our usual manager of mirth?" },
    { r = {"THESEUS"}, t = "What revels are in hand? Is there no play" },
    { r = {"THESEUS"}, t = "To ease the anguish of a torturing hour?" },
    { r = {"THESEUS"}, t = "Call Philostrate." },
    { r = {"PHILOSTRATE"}, t = "Here, mighty Theseus." },
    { r = {"THESEUS"}, t = "Say, what abridgment have you for this evening?" },
    { r = {"THESEUS"}, t = "What masque? What music? How shall we beguile" },
    { r = {"THESEUS"}, t = "The lazy time, if not with some delight?" },
    { r = {"PHILOSTRATE"}, t = "There is a brief how many sports are ripe." },
    { r = {"PHILOSTRATE"}, t = "Make choice of which your Highness will see first." },
    { d = "Giving a paper" },
    { r = {"THESEUS"}, t = "‘The battle with the Centaurs, to be sung", d = "Reads" },
    { r = {"THESEUS"}, t = "By an Athenian eunuch to the harp.’" },
    { r = {"THESEUS"}, t = "We’ll none of that. That have I told my love" },
    { r = {"THESEUS"}, t = "In glory of my kinsman Hercules." },
    { r = {"THESEUS"}, t = "‘The riot of the tipsy Bacchanals," },
    { r = {"THESEUS"}, t = "Tearing the Thracian singer in their rage?’" },
    { r = {"THESEUS"}, t = "That is an old device, and it was play’d" },
    { r = {"THESEUS"}, t = "When I from Thebes came last a conqueror." },
    { r = {"THESEUS"}, t = "‘The thrice three Muses mourning for the death" },
    { r = {"THESEUS"}, t = "Of learning, late deceas’d in beggary.’" },
    { r = {"THESEUS"}, t = "That is some satire, keen and critical," },
    { r = {"THESEUS"}, t = "Not sorting with a nuptial ceremony." },
    { r = {"THESEUS"}, t = "‘A tedious brief scene of young Pyramus" },
    { r = {"THESEUS"}, t = "And his love Thisbe; very tragical mirth.’" },
    { r = {"THESEUS"}, t = "Merry and tragical? Tedious and brief?" },
    { r = {"THESEUS"}, t = "That is hot ice and wondrous strange snow." },
    { r = {"THESEUS"}, t = "How shall we find the concord of this discord?" },
    { r = {"PHILOSTRATE"}, t = "A play there is, my lord, some ten words long," },
    { r = {"PHILOSTRATE"}, t = "Which is as brief as I have known a play;" },
    { r = {"PHILOSTRATE"}, t = "But by ten words, my lord, it is too long," },
    { r = {"PHILOSTRATE"}, t = "Which makes it tedious. For in all the play" },
    { r = {"PHILOSTRATE"}, t = "There is not one word apt, one player fitted." },
    { r = {"PHILOSTRATE"}, t = "And tragical, my noble lord, it is." },
    { r = {"PHILOSTRATE"}, t = "For Pyramus therein doth kill himself," },
    { r = {"PHILOSTRATE"}, t = "Which, when I saw rehears’d, I must confess," },
    { r = {"PHILOSTRATE"}, t = "Made mine eyes water; but more merry tears" },
    { r = {"PHILOSTRATE"}, t = "The passion of loud laughter never shed." },
    { r = {"THESEUS"}, t = "What are they that do play it?" },
    { r = {"PHILOSTRATE"}, t = "Hard-handed men that work in Athens here," },
    { r = {"PHILOSTRATE"}, t = "Which never labour’d in their minds till now;" },
    { r = {"PHILOSTRATE"}, t = "And now have toil’d their unbreath’d memories" },
    { r = {"PHILOSTRATE"}, t = "With this same play against your nuptial." },
    { r = {"THESEUS"}, t = "And we will hear it." },
    { r = {"PHILOSTRATE"}, t = "No, my noble lord," },
    { r = {"PHILOSTRATE"}, t = "It is not for you: I have heard it over," },
    { r = {"PHILOSTRATE"}, t = "And it is nothing, nothing in the world;" },
    { r = {"PHILOSTRATE"}, t = "Unless you can find sport in their intents," },
    { r = {"PHILOSTRATE"}, t = "Extremely stretch’d and conn’d with cruel pain" },
    { r = {"PHILOSTRATE"}, t = "To do you service." },
    { r = {"THESEUS"}, t = "I will hear that play;" },
    { r = {"THESEUS"}, t = "For never anything can be amiss" },
    { r = {"THESEUS"}, t = "When simpleness and duty tender it." },
    { r = {"THESEUS"}, t = "Go, bring them in: and take your places, ladies." },
    { d = "Exit Philostrate" },
    { r = {"HIPPOLYTA"}, t = "I love not to see wretchedness o’ercharged," },
    { r = {"HIPPOLYTA"}, t = "And duty in his service perishing." },
    { r = {"THESEUS"}, t = "Why, gentle sweet, you shall see no such thing." },
    { r = {"HIPPOLYTA"}, t = "He says they can do nothing in this kind." },
    { r = {"THESEUS"}, t = "The kinder we, to give them thanks for nothing." },
    { r = {"THESEUS"}, t = "Our sport shall be to take what they mistake:" },
    { r = {"THESEUS"}, t = "And what poor duty cannot do, noble respect" },
    { r = {"THESEUS"}, t = "Takes it in might, not merit." },
    { r = {"THESEUS"}, t = "Where I have come, great clerks have purposed" },
    { r = {"THESEUS"}, t = "To greet me with premeditated welcomes;" },
    { r = {"THESEUS"}, t = "Where I have seen them shiver and look pale," },
    { r = {"THESEUS"}, t = "Make periods in the midst of sentences," },
    { r = {"THESEUS"}, t = "Throttle their practis’d accent in their fears," },
    { r = {"THESEUS"}, t = "And, in conclusion, dumbly have broke off," },
    { r = {"THESEUS"}, t = "Not paying me a welcome. Trust me, sweet," },
    { r = {"THESEUS"}, t = "Out of this silence yet I pick’d a welcome;" },
    { r = {"THESEUS"}, t = "And in the modesty of fearful duty" },
    { r = {"THESEUS"}, t = "I read as much as from the rattling tongue" },
    { r = {"THESEUS"}, t = "Of saucy and audacious eloquence." },
    { r = {"THESEUS"}, t = "Love, therefore, and tongue-tied simplicity" },
    { r = {"THESEUS"}, t = "In least speak most to my capacity." },
    { d = "Enter Philostrate" },
    { r = {"PHILOSTRATE"}, t = "So please your grace, the Prologue is address’d." },
    { r = {"THESEUS"}, t = "Let him approach." },
    { r = {"THESEUS"}, t = "Flourish of trumpets. Enter the Prologue." },
    { r = {"THESEUS"}, t = "PROLOGUE" },
    { r = {"THESEUS"}, t = "If we offend, it is with our good will." },
    { r = {"THESEUS"}, t = "That you should think, we come not to offend," },
    { r = {"THESEUS"}, t = "But with good will.  To show our simple skill," },
    { r = {"THESEUS"}, t = "That is the true beginning of our end." },
    { r = {"THESEUS"}, t = "Consider then, we come but in despite." },
    { r = {"THESEUS"}, t = "We do not come, as minding to content you," },
    { r = {"THESEUS"}, t = "Our true intent is.  All for your delight" },
    { r = {"THESEUS"}, t = "We are not here.  That you should here repent you," },
    { r = {"THESEUS"}, t = "The actors are at hand, and, by their show," },
    { r = {"THESEUS"}, t = "You shall know all that you are like to know." },
    { r = {"THESEUS"}, t = "This fellow doth not stand upon points." },
    { r = {"LYSANDER"}, t = "He hath rid his prologue like a rough colt; he knows not the stop." },
    { r = {"LYSANDER"}, t = "A good moral, my lord: it is not enough to speak, but to speak true." },
    { r = {"HIPPOLYTA"}, t = "Indeed he hath played on this prologue like a child on a recorder; a sound, but not in government." },
    { r = {"THESEUS"}, t = "His speech was like a tangled chain; nothing impaired, but all disordered." },
    { r = {"THESEUS"}, t = "Who is next?" },
    { d = "Enter Pyramus and Thisbe, Wall, Moonshine and Lion as in dumb show" },
    { r = {"THESEUS"}, t = "PROLOGUE" },
    { r = {"THESEUS"}, t = "Gentles, perchance you wonder at this show;" },
    { r = {"THESEUS"}, t = "But wonder on, till truth make all things plain." },
    { r = {"THESEUS"}, t = "This man is Pyramus, if you would know;" },
    { r = {"THESEUS"}, t = "This beauteous lady Thisbe is certain." },
    { r = {"THESEUS"}, t = "This man, with lime and rough-cast, doth present" },
    { r = {"THESEUS"}, t = "Wall, that vile wall which did these lovers sunder;" },
    { r = {"THESEUS"}, t = "And through Wall’s chink, poor souls, they are content" },
    { r = {"THESEUS"}, t = "To whisper, at the which let no man wonder." },
    { r = {"THESEUS"}, t = "This man, with lantern, dog, and bush of thorn," },
    { r = {"THESEUS"}, t = "Presenteth Moonshine, for, if you will know," },
    { r = {"THESEUS"}, t = "By moonshine did these lovers think no scorn" },
    { r = {"THESEUS"}, t = "To meet at Ninus’ tomb, there, there to woo." },
    { r = {"THESEUS"}, t = "This grisly beast (which Lion hight by name)" },
    { r = {"THESEUS"}, t = "The trusty Thisbe, coming first by night," },
    { r = {"THESEUS"}, t = "Did scare away, or rather did affright;" },
    { r = {"THESEUS"}, t = "And as she fled, her mantle she did fall;" },
    { r = {"THESEUS"}, t = "Which Lion vile with bloody mouth did stain." },
    { r = {"THESEUS"}, t = "Anon comes Pyramus, sweet youth, and tall," },
    { r = {"THESEUS"}, t = "And finds his trusty Thisbe’s mantle slain;" },
    { r = {"THESEUS"}, t = "Whereat with blade, with bloody blameful blade," },
    { r = {"THESEUS"}, t = "He bravely broach’d his boiling bloody breast;" },
    { r = {"THESEUS"}, t = "And Thisbe, tarrying in mulberry shade," },
    { r = {"THESEUS"}, t = "His dagger drew, and died. For all the rest," },
    { r = {"THESEUS"}, t = "Let Lion, Moonshine, Wall, and lovers twain," },
    { r = {"THESEUS"}, t = "At large discourse while here they do remain." },
    { d = "Exeunt Prologue, Pyramus, Thisbe, Lion and Moonshine" },
    { r = {"THESEUS"}, t = "I wonder if the lion be to speak." },
    { r = {"DEMETRIUS"}, t = "No wonder, my lord. One lion may, when many asses do." },
    { r = {"WALL"}, t = "In this same interlude it doth befall" },
    { r = {"WALL"}, t = "That I, one Snout by name, present a wall:" },
    { r = {"WALL"}, t = "And such a wall as I would have you think" },
    { r = {"WALL"}, t = "That had in it a crannied hole or chink," },
    { r = {"WALL"}, t = "Through which the lovers, Pyramus and Thisbe," },
    { r = {"WALL"}, t = "Did whisper often very secretly." },
    { r = {"WALL"}, t = "This loam, this rough-cast, and this stone, doth show" },
    { r = {"WALL"}, t = "That I am that same wall; the truth is so:" },
    { r = {"WALL"}, t = "And this the cranny is, right and sinister," },
    { r = {"WALL"}, t = "Through which the fearful lovers are to whisper." },
    { r = {"THESEUS"}, t = "Would you desire lime and hair to speak better?" },
    { r = {"DEMETRIUS"}, t = "It is the wittiest partition that ever I heard discourse, my lord." },
    { r = {"THESEUS"}, t = "Pyramus draws near the wall; silence." },
    { d = "Enter Pyramus" },
    { r = {"PYRAMUS"}, t = "O grim-look’d night! O night with hue so black!" },
    { r = {"PYRAMUS"}, t = "O night, which ever art when day is not!" },
    { r = {"PYRAMUS"}, t = "O night, O night, alack, alack, alack," },
    { r = {"PYRAMUS"}, t = "I fear my Thisbe’s promise is forgot!" },
    { r = {"PYRAMUS"}, t = "And thou, O wall, O sweet, O lovely wall," },
    { r = {"PYRAMUS"}, t = "That stand’st between her father’s ground and mine;" },
    { r = {"PYRAMUS"}, t = "Thou wall, O wall, O sweet and lovely wall," },
    { r = {"PYRAMUS"}, t = "Show me thy chink, to blink through with mine eyne." },
    { d = "Wall holds up his fingers" },
    { r = {"PYRAMUS"}, t = "Thanks, courteous wall: Jove shield thee well for this!" },
    { r = {"PYRAMUS"}, t = "But what see I? No Thisbe do I see." },
    { r = {"PYRAMUS"}, t = "O wicked wall, through whom I see no bliss," },
    { r = {"PYRAMUS"}, t = "Curs’d be thy stones for thus deceiving me!" },
    { r = {"THESEUS"}, t = "The wall, methinks, being sensible, should curse again." },
    { r = {"PYRAMUS"}, t = "No, in truth, sir, he should not." },
    { r = {"PYRAMUS"}, t = "‘Deceiving me’ is Thisbe’s cue: she is to enter now, and I am to spy her through the wall." },
    { r = {"PYRAMUS"}, t = "You shall see it will fall pat as I told you." },
    { r = {"PYRAMUS"}, t = "Yonder she comes." },
    { d = "Enter Thisbe" },
    { r = {"THISBE"}, t = "O wall, full often hast thou heard my moans," },
    { r = {"THISBE"}, t = "For parting my fair Pyramus and me." },
    { r = {"THISBE"}, t = "My cherry lips have often kiss’d thy stones," },
    { r = {"THISBE"}, t = "Thy stones with lime and hair knit up in thee." },
    { r = {"PYRAMUS"}, t = "I see a voice; now will I to the chink," },
    { r = {"PYRAMUS"}, t = "To spy an I can hear my Thisbe’s face." },
    { r = {"PYRAMUS"}, t = "Thisbe?" },
    { r = {"THISBE"}, t = "My love thou art, my love I think." },
    { r = {"PYRAMUS"}, t = "Think what thou wilt, I am thy lover’s grace;" },
    { r = {"PYRAMUS"}, t = "And like Limander am I trusty still." },
    { r = {"THISBE"}, t = "And I like Helen, till the fates me kill." },
    { r = {"PYRAMUS"}, t = "Not Shafalus to Procrus was so true." },
    { r = {"THISBE"}, t = "As Shafalus to Procrus, I to you." },
    { r = {"PYRAMUS"}, t = "O kiss me through the hole of this vile wall." },
    { r = {"THISBE"}, t = "I kiss the wall’s hole, not your lips at all." },
    { r = {"PYRAMUS"}, t = "Wilt thou at Ninny’s tomb meet me straightway?" },
    { r = {"THISBE"}, t = "’Tide life, ’tide death, I come without delay." },
    { r = {"WALL"}, t = "Thus have I, Wall, my part discharged so;" },
    { r = {"WALL"}, t = "And, being done, thus Wall away doth go." },
    { d = "Exeunt Wall, Pyramus and Thisbe" },
    { r = {"THESEUS"}, t = "Now is the mural down between the two neighbours." },
    { r = {"DEMETRIUS"}, t = "No remedy, my lord, when walls are so wilful to hear without warning." },
    { r = {"HIPPOLYTA"}, t = "This is the silliest stuff that ever I heard." },
    { r = {"THESEUS"}, t = "The best in this kind are but shadows; and the worst are no worse, if imagination amend them." },
    { r = {"HIPPOLYTA"}, t = "It must be your imagination then, and not theirs." },
    { r = {"THESEUS"}, t = "If we imagine no worse of them than they of themselves, they may pass for excellent men." },
    { r = {"THESEUS"}, t = "Here come two noble beasts in, a man and a lion." },
    { d = "Enter Lion and Moonshine" },
    { r = {"LION"}, t = "You, ladies, you, whose gentle hearts do fear" },
    { r = {"LION"}, t = "The smallest monstrous mouse that creeps on floor," },
    { r = {"LION"}, t = "May now, perchance, both quake and tremble here," },
    { r = {"LION"}, t = "When lion rough in wildest rage doth roar." },
    { r = {"LION"}, t = "Then know that I, one Snug the joiner, am" },
    { r = {"LION"}, t = "A lion fell, nor else no lion’s dam;" },
    { r = {"LION"}, t = "For if I should as lion come in strife" },
    { r = {"LION"}, t = "Into this place, ’twere pity on my life." },
    { r = {"THESEUS"}, t = "A very gentle beast, and of a good conscience." },
    { r = {"DEMETRIUS"}, t = "The very best at a beast, my lord, that e’er I saw." },
    { r = {"LYSANDER"}, t = "This lion is a very fox for his valour." },
    { r = {"THESEUS"}, t = "True; and a goose for his discretion." },
    { r = {"DEMETRIUS"}, t = "Not so, my lord, for his valour cannot carry his discretion, and the fox carries the goose." },
    { r = {"THESEUS"}, t = "His discretion, I am sure, cannot carry his valour; for the goose carries not the fox." },
    { r = {"THESEUS"}, t = "It is well; leave it to his discretion, and let us listen to the moon." },
    { r = {"MOONSHINE"}, t = "This lanthorn doth the hornèd moon present." },
    { r = {"DEMETRIUS"}, t = "He should have worn the horns on his head." },
    { r = {"THESEUS"}, t = "He is no crescent, and his horns are invisible within the circumference." },
    { r = {"MOONSHINE"}, t = "This lanthorn doth the hornèd moon present;" },
    { r = {"MOONSHINE"}, t = "Myself the man i’ the moon do seem to be." },
    { r = {"THESEUS"}, t = "This is the greatest error of all the rest; the man should be put into the lantern." },
    { r = {"THESEUS"}, t = "How is it else the man i’ the moon?" },
    { r = {"DEMETRIUS"}, t = "He dares not come there for the candle, for you see, it is already in snuff." },
    { r = {"HIPPOLYTA"}, t = "I am aweary of this moon. Would he would change!" },
    { r = {"THESEUS"}, t = "It appears by his small light of discretion that he is in the wane; but yet, in courtesy, in all reason, we must stay the time." },
    { r = {"LYSANDER"}, t = "Proceed, Moon." },
    { r = {"MOON"}, t = "All that I have to say, is to tell you that the lantern is the moon; I the man i’ the moon; this thorn-bush my thorn-bush; and this dog my dog." },
    { r = {"DEMETRIUS"}, t = "Why, all these should be in the lantern, for all these are in the moon." },
    { r = {"DEMETRIUS"}, t = "But silence; here comes Thisbe." },
    { d = "Enter Thisbe" },
    { r = {"THISBE"}, t = "This is old Ninny’s tomb. Where is my love?" },
    { r = {"LION"}, t = "Oh!" },
    { d = "The Lion roars, Thisbe runs off" },
    { r = {"DEMETRIUS"}, t = "Well roared, Lion." },
    { r = {"THESEUS"}, t = "Well run, Thisbe." },
    { r = {"HIPPOLYTA"}, t = "Well shone, Moon. Truly, the moon shines with a good grace." },
    { d = "The Lion tears Thisbe’s mantle, and exit" },
    { r = {"THESEUS"}, t = "Well moused, Lion." },
    { r = {"DEMETRIUS"}, t = "And then came Pyramus." },
    { r = {"LYSANDER"}, t = "And so the lion vanished." },
    { d = "Enter Pyramus" },
    { r = {"PYRAMUS"}, t = "Sweet Moon, I thank thee for thy sunny beams;" },
    { r = {"PYRAMUS"}, t = "I thank thee, Moon, for shining now so bright;" },
    { r = {"PYRAMUS"}, t = "For, by thy gracious golden, glittering gleams," },
    { r = {"PYRAMUS"}, t = "I trust to take of truest Thisbe sight." },
    { r = {"PYRAMUS"}, t = "But stay! O spite!" },
    { r = {"PYRAMUS"}, t = "But mark, poor knight," },
    { r = {"PYRAMUS"}, t = "What dreadful dole is here!" },
    { r = {"PYRAMUS"}, t = "Eyes, do you see?" },
    { r = {"PYRAMUS"}, t = "How can it be?" },
    { r = {"PYRAMUS"}, t = "O dainty duck! O dear!" },
    { r = {"PYRAMUS"}, t = "Thy mantle good," },
    { r = {"PYRAMUS"}, t = "What, stained with blood?" },
    { r = {"PYRAMUS"}, t = "Approach, ye Furies fell!" },
    { r = {"PYRAMUS"}, t = "O Fates, come, come;" },
    { r = {"PYRAMUS"}, t = "Cut thread and thrum;" },
    { r = {"PYRAMUS"}, t = "Quail, rush, conclude, and quell!" },
    { r = {"THESEUS"}, t = "This passion, and the death of a dear friend, would go near to make a man look sad." },
    { r = {"HIPPOLYTA"}, t = "Beshrew my heart, but I pity the man." },
    { r = {"PYRAMUS"}, t = "O wherefore, Nature, didst thou lions frame," },
    { r = {"PYRAMUS"}, t = "Since lion vile hath here deflower’d my dear?" },
    { r = {"PYRAMUS"}, t = "Which is—no, no—which was the fairest dame" },
    { r = {"PYRAMUS"}, t = "That liv’d, that lov’d, that lik’d, that look’d with cheer." },
    { r = {"PYRAMUS"}, t = "Come, tears, confound!" },
    { r = {"PYRAMUS"}, t = "Out, sword, and wound" },
    { r = {"PYRAMUS"}, t = "The pap of Pyramus;" },
    { r = {"PYRAMUS"}, t = "Ay, that left pap," },
    { r = {"PYRAMUS"}, t = "Where heart doth hop:" },
    { r = {"PYRAMUS"}, t = "Thus die I, thus, thus, thus." },
    { r = {"PYRAMUS"}, t = "Now am I dead," },
    { r = {"PYRAMUS"}, t = "Now am I fled;" },
    { r = {"PYRAMUS"}, t = "My soul is in the sky." },
    { r = {"PYRAMUS"}, t = "Tongue, lose thy light!" },
    { r = {"PYRAMUS"}, t = "Moon, take thy flight!" },
    { r = {"PYRAMUS"}, t = "Now die, die, die, die, die." },
    { r = {"PYRAMUS"}, d = "Dies. Exit Moonshine", e = "/lie", s = {"Feign Death"} },
    { r = {"DEMETRIUS"}, t = "No die, but an ace, for him; for he is but one." },
    { r = {"LYSANDER"}, t = "Less than an ace, man; for he is dead, he is nothing." },
    { r = {"THESEUS"}, t = "With the help of a surgeon he might yet recover and prove an ass." },
    { r = {"HIPPOLYTA"}, t = "How chance Moonshine is gone before Thisbe comes back and finds her lover?" },
    { r = {"THESEUS"}, t = "She will find him by starlight." },
    { d = "Enter Thisbe" },
    { r = {"THESEUS"}, t = "Here she comes, and her passion ends the play." },
    { r = {"HIPPOLYTA"}, t = "Methinks she should not use a long one for such a Pyramus." },
    { r = {"HIPPOLYTA"}, t = "I hope she will be brief." },
    { r = {"DEMETRIUS"}, t = "A mote will turn the balance, which Pyramus, which Thisbe, is the better: he for a man, God warrant us; she for a woman, God bless us!" },
    { r = {"LYSANDER"}, t = "She hath spied him already with those sweet eyes." },
    { r = {"DEMETRIUS"}, t = "And thus she means, videlicet" },
    { r = {"THISBE"}, t = "Asleep, my love?" },
    { r = {"THISBE"}, t = "What, dead, my dove?" },
    { r = {"THISBE"}, t = "O Pyramus, arise," },
    { r = {"THISBE"}, t = "Speak, speak. Quite dumb?" },
    { r = {"THISBE"}, t = "Dead, dead? A tomb" },
    { r = {"THISBE"}, t = "Must cover thy sweet eyes." },
    { r = {"THISBE"}, t = "These lily lips," },
    { r = {"THISBE"}, t = "This cherry nose," },
    { r = {"THISBE"}, t = "These yellow cowslip cheeks," },
    { r = {"THISBE"}, t = "Are gone, are gone!" },
    { r = {"THISBE"}, t = "Lovers, make moan;" },
    { r = {"THISBE"}, t = "His eyes were green as leeks." },
    { r = {"THISBE"}, t = "O Sisters Three," },
    { r = {"THISBE"}, t = "Come, come to me," },
    { r = {"THISBE"}, t = "With hands as pale as milk;" },
    { r = {"THISBE"}, t = "Lay them in gore," },
    { r = {"THISBE"}, t = "Since you have shore" },
    { r = {"THISBE"}, t = "With shears his thread of silk." },
    { r = {"THISBE"}, t = "Tongue, not a word:" },
    { r = {"THISBE"}, t = "Come, trusty sword," },
    { r = {"THISBE"}, t = "Come, blade, my breast imbrue;" },
    { r = {"THISBE"}, t = "And farewell, friends." },
    { r = {"THISBE"}, t = "Thus Thisbe ends." },
    { r = {"THISBE"}, t = "Adieu, adieu, adieu." },
    { r = {"THISBE"}, d = "Dies", e = "/lie", s = {"Feign Death"} },
    { r = {"THESEUS"}, t = "Moonshine and Lion are left to bury the dead." },
    { r = {"DEMETRIUS"}, t = "Ay, and Wall too." },
    { r = {"BOTTOM"}, t = "No, I assure you; the wall is down that parted their fathers." },
    { r = {"BOTTOM"}, t = "Will it please you to see the epilogue, or to hear a Bergomask dance between two of our company?" },
    { r = {"THESEUS"}, t = "No epilogue, I pray you; for your play needs no excuse." },
    { r = {"THESEUS"}, t = "Never excuse; for when the players are all dead there need none to be blamed." },
    { r = {"THESEUS"}, t = "Marry, if he that writ it had played Pyramus, and hanged himself in Thisbe’s garter, it would have been a fine tragedy; and so it is, truly; and very notably discharged." },
    { r = {"THESEUS"}, t = "But come, your Bergomask; let your epilogue alone." },
    { d = "Here a dance of Clowns" },
    { r = {"THESEUS"}, t = "The iron tongue of midnight hath told twelve." },
    { r = {"THESEUS"}, t = "Lovers, to bed; ’tis almost fairy time." },
    { r = {"THESEUS"}, t = "I fear we shall outsleep the coming morn" },
    { r = {"THESEUS"}, t = "As much as we this night have overwatch’d." },
    { r = {"THESEUS"}, t = "This palpable-gross play hath well beguil’d" },
    { r = {"THESEUS"}, t = "The heavy gait of night. Sweet friends, to bed." },
    { r = {"THESEUS"}, t = "A fortnight hold we this solemnity" },
    { r = {"THESEUS"}, t = "In nightly revels and new jollity." },
    { d = "Exeunt" },
    { d = "Enter Puck" },
    { r = {"PUCK"}, t = "Now the hungry lion roars," },
    { r = {"PUCK"}, t = "And the wolf behowls the moon;" },
    { r = {"PUCK"}, t = "Whilst the heavy ploughman snores," },
    { r = {"PUCK"}, t = "All with weary task fordone." },
    { r = {"PUCK"}, t = "Now the wasted brands do glow," },
    { r = {"PUCK"}, t = "Whilst the screech-owl, screeching loud," },
    { r = {"PUCK"}, t = "Puts the wretch that lies in woe" },
    { r = {"PUCK"}, t = "In remembrance of a shroud." },
    { r = {"PUCK"}, t = "Now it is the time of night" },
    { r = {"PUCK"}, t = "That the graves, all gaping wide," },
    { r = {"PUCK"}, t = "Every one lets forth his sprite," },
    { r = {"PUCK"}, t = "In the church-way paths to glide." },
    { r = {"PUCK"}, t = "And we fairies, that do run" },
    { r = {"PUCK"}, t = "By the triple Hecate’s team" },
    { r = {"PUCK"}, t = "From the presence of the sun," },
    { r = {"PUCK"}, t = "Following darkness like a dream," },
    { r = {"PUCK"}, t = "Now are frolic; not a mouse" },
    { r = {"PUCK"}, t = "Shall disturb this hallow’d house." },
    { r = {"PUCK"}, t = "I am sent with broom before," },
    { r = {"PUCK"}, t = "To sweep the dust behind the door." },
    { d = "Enter Oberon and Titania with their Train" },
    { r = {"OBERON"}, t = "Through the house give glimmering light," },
    { r = {"OBERON"}, t = "By the dead and drowsy fire." },
    { r = {"OBERON"}, t = "Every elf and fairy sprite" },
    { r = {"OBERON"}, t = "Hop as light as bird from brier," },
    { r = {"OBERON"}, t = "And this ditty after me," },
    { r = {"OBERON"}, t = "Sing and dance it trippingly." },
    { r = {"TITANIA"}, t = "First rehearse your song by rote," },
    { r = {"TITANIA"}, t = "To each word a warbling note;" },
    { r = {"TITANIA"}, t = "Hand in hand, with fairy grace," },
    { r = {"TITANIA"}, t = "Will we sing, and bless this place." },
    { d = "Song and Dance" },
    { r = {"OBERON"}, t = "Now, until the break of day," },
    { r = {"OBERON"}, t = "Through this house each fairy stray." },
    { r = {"OBERON"}, t = "To the best bride-bed will we," },
    { r = {"OBERON"}, t = "Which by us shall blessèd be;" },
    { r = {"OBERON"}, t = "And the issue there create" },
    { r = {"OBERON"}, t = "Ever shall be fortunate." },
    { r = {"OBERON"}, t = "So shall all the couples three" },
    { r = {"OBERON"}, t = "Ever true in loving be;" },
    { r = {"OBERON"}, t = "And the blots of Nature’s hand" },
    { r = {"OBERON"}, t = "Shall not in their issue stand:" },
    { r = {"OBERON"}, t = "Never mole, hare-lip, nor scar," },
    { r = {"OBERON"}, t = "Nor mark prodigious, such as are" },
    { r = {"OBERON"}, t = "Despised in nativity," },
    { r = {"OBERON"}, t = "Shall upon their children be." },
    { r = {"OBERON"}, t = "With this field-dew consecrate," },
    { r = {"OBERON"}, t = "Every fairy take his gait," },
    { r = {"OBERON"}, t = "And each several chamber bless," },
    { r = {"OBERON"}, t = "Through this palace, with sweet peace;" },
    { r = {"OBERON"}, t = "And the owner of it blest." },
    { r = {"OBERON"}, t = "Ever shall it in safety rest," },
    { r = {"OBERON"}, t = "Trip away. Make no stay;" },
    { r = {"OBERON"}, t = "Meet me all by break of day." },
    { d = "Exeunt Oberon, Titania and Train" },
    { r = {"PUCK"}, t = "If we shadows have offended," },
    { r = {"PUCK"}, t = "Think but this, and all is mended," },
    { r = {"PUCK"}, t = "That you have but slumber’d here" },
    { r = {"PUCK"}, t = "While these visions did appear." },
    { r = {"PUCK"}, t = "And this weak and idle theme," },
    { r = {"PUCK"}, t = "No more yielding but a dream," },
    { r = {"PUCK"}, t = "Gentles, do not reprehend." },
    { r = {"PUCK"}, t = "If you pardon, we will mend." },
    { r = {"PUCK"}, t = "And, as I am an honest Puck," },
    { r = {"PUCK"}, t = "If we have unearnèd luck" },
    { r = {"PUCK"}, t = "Now to ’scape the serpent’s tongue," },
    { r = {"PUCK"}, t = "We will make amends ere long;" },
    { r = {"PUCK"}, t = "Else the Puck a liar call." },
    { r = {"PUCK"}, t = "So, good night unto you all." },
    { r = {"PUCK"}, t = "Give me your hands, if we be friends," },
    { r = {"PUCK"}, t = "And Robin shall restore amends." },
    { d = "Exit" },
  },
}
